    { const char * tb_v897 = "TB_API double atan(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v897; }
    { const char * tb_v898 = "    if (x < 0) return -atan(-x);\n"; *(const char * *)tb_grow(v_lines) = tb_v898; }
