    { const char * tb_v905 = "TB_API double atan2(double y, double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v905; }
    { const char * tb_v906 = "    const double pi = 3.14159265358979323846;\n"; *(const char * *)tb_grow(v_lines) = tb_v906; }
    { const char * tb_v907 = "    if (x > 0) return atan(y / x);\n"; *(const char * *)tb_grow(v_lines) = tb_v907; }
    { const char * tb_v908 = "    if (x < 0) return y >= 0 ? atan(y / x) + pi : atan(y / x) - pi;\n"; *(const char * *)tb_grow(v_lines) = tb_v908; }
    { const char * tb_v909 = "    return y > 0 ? pi / 2 : y < 0 ? -pi / 2 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v909; }
    { const char * tb_v910 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v910; }
    { const char * tb_v911 = "TB_API double exp(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v911; }
    { const char * tb_v912 = "    if (x > 709) return 1e308;\n"; *(const char * *)tb_grow(v_lines) = tb_v912; }
    { const char * tb_v913 = "    if (x < -745) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v913; }
    { const char * tb_v914 = "    long long k = (long long)floor(x / 0.6931471805599453 + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v914; }
    { const char * tb_v915 = "    double r = x - (double)k * 0.6931471805599453, t = 1, s = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v915; }
    { const char * tb_v916 = "    for (int i = 1; i < 18; i++) { t *= r / i; s += t; }\n"; *(const char * *)tb_grow(v_lines) = tb_v916; }
