    { const char * tb_v918 = "    v.u += (unsigned long long)k << 52;\n"; *(const char * *)tb_grow(v_lines) = tb_v918; }
    { const char * tb_v919 = "    return v.d;\n"; *(const char * *)tb_grow(v_lines) = tb_v919; }
    { const char * tb_v920 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v920; }
    { const char * tb_v921 = "TB_API double log(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v921; }
    { const char * tb_v922 = "    if (x <= 0) return -1e308;\n"; *(const char * *)tb_grow(v_lines) = tb_v922; }
    { const char * tb_v923 = "    union { double d; unsigned long long u; } v; v.d = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v923; }
    { const char * tb_v924 = "    long long e = (long long)((v.u >> 52) & 0x7FF) - 1023;\n"; *(const char * *)tb_grow(v_lines) = tb_v924; }
    { const char * tb_v925 = "    v.u = (v.u & 0x000FFFFFFFFFFFFFull) | 0x3FF0000000000000ull;   // 1 <= m < 2\n"; *(const char * *)tb_grow(v_lines) = tb_v925; }
    { const char * tb_v926 = "    double m = v.d;\n"; *(const char * *)tb_grow(v_lines) = tb_v926; }
    { const char * tb_v927 = "    if (m > 1.4142135623730951) { m /= 2; e++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v927; }
    { const char * tb_v928 = "    double y = (m - 1) / (m + 1), y2 = y * y, t = y, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v928; }
    { const char * tb_v929 = "    for (int k = 0; k < 20; k++) { r += t / (2 * k + 1); t *= y2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v929; }
