    { const char * tb_v931 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v931; }
    { const char * tb_v932 = "TB_API double pow(double a, double b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v932; }
    { const char * tb_v933 = "    if (b == 0) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v933; }
    { const char * tb_v934 = "    if (a == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v934; }
    { const char * tb_v935 = "    if (b == (double)(long long)b && b > -64 && b < 64) {\n"; *(const char * *)tb_grow(v_lines) = tb_v935; }
    { const char * tb_v936 = "        double r = 1, m = a; long long n = (long long)(b < 0 ? -b : b);\n"; *(const char * *)tb_grow(v_lines) = tb_v936; }
    { const char * tb_v937 = "        while (n) { if (n & 1) r *= m; m *= m; n >>= 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v937; }
    { const char * tb_v938 = "        return b < 0 ? 1 / r : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v938; }
    { const char * tb_v939 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v939; }
    { const char * tb_v940 = "    if (a < 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v940; }
