    { const char * tb_v942 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v942; }
    { const char * tb_v943 = "TB_API float powf(float a, float b) { return (float)pow(a, b); }\n"; *(const char * *)tb_grow(v_lines) = tb_v943; }
    { const char * tb_v944 = "TB_API void *bsearch(const void *key, const void *base, size_t n, size_t size, int (*cmp)(const void *, const void *)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v944; }
    { const char * tb_v945 = "    size_t lo = 0, hi = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v945; }
