    { const char * tb_v995 = "        \".set tb_v, 0\\n.rept 50\\n.balign 16\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v995; }
    { const char * tb_v996 = "        \".if (tb_v == 8) || (tb_v == 10) || (tb_v == 11) || (tb_v == 12) || (tb_v == 13) || (tb_v == 14) || (tb_v == 17) || (tb_v == 21)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v996; }
    { const char * tb_v997 = "        \".else\\npushq $0\\n.endif\\npushq $tb_v\\njmp tb_isr_common\\n.set tb_v, tb_v + 1\\n.endr\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v997; }
    { const char * tb_v998 = "        \"tb_isr_common:\\ncld\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v998; }
    { const char * tb_v999 = "        \"pushq %rax\\npushq %rcx\\npushq %rdx\\npushq %rbx\\npushq %rbp\\npushq %rsi\\npushq %rdi\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v999; }
