    { const char * tb_v1270 = "// таблица имён ядра (её заполняет компоновщик elf_link.py): по алфавиту, 16 байт на имя —\n"; *(const char * *)tb_grow(v_lines) = tb_v1270; }
    { const char * tb_v1271 = "// адрес, где имя (от начала таблицы), длина имени. Программы Омниума находят по ней функции ядра\n"; *(const char * *)tb_grow(v_lines) = tb_v1271; }
    { const char * tb_v1272 = "TB_API volatile uint64_t tb_ksym_tab __attribute__((used)) = 1, tb_ksym_n __attribute__((used)) = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1272; }
