    { const char * tb_v1928 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v1928; }
    { const char * tb_v1929 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v1929; }
