    { const char * tb_v2158 = "    // первый кусок оставляем пустым: следующий temp возьмёт его без malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v2158; }
    { const char * tb_v2159 = "    while (tb_nchunks > m.n && tb_nchunks > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2159; }
    { const char * tb_v2160 = "        tb_nchunks -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2160; }
    { const char * tb_v2161 = "        free(tb_chunks[tb_nchunks].mem);\n"; *(const char * *)tb_grow(v_lines) = tb_v2161; }
    { const char * tb_v2162 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2162; }
    { const char * tb_v2163 = "    if (tb_nchunks > m.n) tb_chunks[0].used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2163; }
    { const char * tb_v2164 = "    else if (tb_nchunks > 0) tb_chunks[tb_nchunks - 1].used = m.used;\n"; *(const char * *)tb_grow(v_lines) = tb_v2164; }
    { const char * tb_v2165 = "    tb_temp_depth -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2165; }
    { const char * tb_v2166 = "    tb_lc_clear();\n"; *(const char * *)tb_grow(v_lines) = tb_v2166; }
    { const char * tb_v2167 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2167; }
    { const char * tb_v2168 = "// --llvm: то же через указатель (из файла .ll так проще, чем отдавать struct по значению)\n"; *(const char * *)tb_grow(v_lines) = tb_v2168; }
    { const char * tb_v2169 = "TB_INL void tb_temp_begin_p(tb_mark *m) { *m = tb_temp_begin(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2169; }
    { const char * tb_v2170 = "TB_INL void tb_temp_end_p(tb_mark *m) { tb_temp_end(*m); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2170; }
    { const char * tb_v2171 = "// память функции: своя область, только если функцию позвали не изнутри другой области\n"; *(const char * *)tb_grow(v_lines) = tb_v2171; }
    { const char * tb_v2172 = "TB_INL int tb_fa_begin(tb_mark *m) { if (tb_temp_depth != 0) return 0; *m = tb_temp_begin(); return 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2172; }
    { const char * tb_v2173 = "TB_INL void tb_fa_end(int fa, tb_mark *m) { if (fa) tb_temp_end(*m); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2173; }
    { const char * tb_v2174 = "// ---------- уборка памяти: сборщик мусора ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2174; }
    { const char * tb_v2175 = "// Шаги циклов, функции и temp уже отдают память сами (своя временная память).\n"; *(const char * *)tb_grow(v_lines) = tb_v2175; }
    { const char * tb_v2176 = "// А то, что живёт дольше (obj, списки, dict, тексты), раньше жило до конца программы.\n"; *(const char * *)tb_grow(v_lines) = tb_v2176; }
    { const char * tb_v2177 = "// Теперь иногда (когда набралось много новой памяти) программа делает обход:\n"; *(const char * *)tb_grow(v_lines) = tb_v2177; }
    { const char * tb_v2178 = "//   1) смотрит, что видно из переменных: стек, общие (shared) переменные, временная память;\n"; *(const char * *)tb_grow(v_lines) = tb_v2178; }
    { const char * tb_v2179 = "//   2) от них идёт по всему, на что они указывают, и помечает это «нужно»;\n"; *(const char * *)tb_grow(v_lines) = tb_v2179; }
    { const char * tb_v2180 = "//   3) всё не помеченное — мусор, его место отдаётся под новые значения.\n"; *(const char * *)tb_grow(v_lines) = tb_v2180; }
    { const char * tb_v2181 = "// Обход идёт, только когда работает один поток: пока идут background или on all cores, ждём.\n"; *(const char * *)tb_grow(v_lines) = tb_v2181; }
    { const char * tb_v2182 = "// TB_GC=0 — выключить уборку (для проверки), TB_GC_STRESS=N — обход на каждом N-м выделении,\n"; *(const char * *)tb_grow(v_lines) = tb_v2182; }
    { const char * tb_v2183 = "// TB_GC_STATS=1 — печатать каждый обход.\n"; *(const char * *)tb_grow(v_lines) = tb_v2183; }
    { const char * tb_v2184 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2184; }
    { const char * tb_v2185 = "TB_API void *tb_gc_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2185; }
    { const char * tb_v2186 = "    void *p = malloc(n > 0 ? n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v2186; }
    { const char * tb_v2187 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2187; }
    { const char * tb_v2188 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2188; }
    { const char * tb_v2189 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2189; }
    { const char * tb_v2190 = "TB_API void tb_gc_free(void *p) { free(p); }\n"; *(const char * *)tb_grow(v_lines) = tb_v2190; }
    { const char * tb_v2191 = "#define tb_gc_alloc_np tb_gc_alloc\n"; *(const char * *)tb_grow(v_lines) = tb_v2191; }
    { const char * tb_v2192 = "TB_API void *tb_gc_realloc(void *p, long long old_n, long long new_n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2192; }
    { const char * tb_v2193 = "    (void)old_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2193; }
    { const char * tb_v2194 = "    p = realloc(p, new_n > 0 ? new_n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v2194; }
    { const char * tb_v2195 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2195; }
    { const char * tb_v2196 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v2196; }
    { const char * tb_v2197 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2197; }
    { const char * tb_v2198 = "#define tb_gc_root(p, n) ((void)(p), (void)(n))\n"; *(const char * *)tb_grow(v_lines) = tb_v2198; }
    { const char * tb_v2199 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2199; }
    { const char * tb_v2200 = "#include <setjmp.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v2200; }
    { const char * tb_v2201 = "#define TB_GSH 16\n"; *(const char * *)tb_grow(v_lines) = tb_v2201; }
    { const char * tb_v2202 = "#define TB_GPG (1LL << TB_GSH)\n"; *(const char * *)tb_grow(v_lines) = tb_v2202; }
