    { const char * tb_v2204 = "#define TB_GBIG 32768\n"; *(const char * *)tb_grow(v_lines) = tb_v2204; }
    { const char * tb_v2205 = "// размеры мелких блоков: страница 64 КБ делится на блоки одного размера (шаг 8 байт у мелких — плотно, как подряд)\n"; *(const char * *)tb_grow(v_lines) = tb_v2205; }
    { const char * tb_v2206 = "TB_API const long long tb_gsz[TB_GNC] = {16, 24, 32, 40, 48, 56, 64, 72, 80, 96, 112, 128, 160, 192, 224, 256,\n"; *(const char * *)tb_grow(v_lines) = tb_v2206; }
    { const char * tb_v2207 = "    320, 384, 448, 512, 640, 768, 1024, 1280, 1536, 2048, 2560, 3072, 4096, 5120, 6144, 8192, 10240, 12288,\n"; *(const char * *)tb_grow(v_lines) = tb_v2207; }
    { const char * tb_v2208 = "    16384, 21840, 32768};\n"; *(const char * *)tb_grow(v_lines) = tb_v2208; }
    { const char * tb_v2209 = "typedef struct tb_gpage {\n"; *(const char * *)tb_grow(v_lines) = tb_v2209; }
    { const char * tb_v2210 = "    char *start;\n"; *(const char * *)tb_grow(v_lines) = tb_v2210; }
    { const char * tb_v2211 = "    long long bsize, nblocks;      // мелкие: размер блока и сколько их\n"; *(const char * *)tb_grow(v_lines) = tb_v2211; }
    { const char * tb_v2212 = "    long long nbytes, cap;         // большой блок: сколько занято и сколько взято\n"; *(const char * *)tb_grow(v_lines) = tb_v2212; }
    { const char * tb_v2213 = "    unsigned long long inv;        // 2^32 / bsize (вверх): номер блока умножением, без деления\n"; *(const char * *)tb_grow(v_lines) = tb_v2213; }
    { const char * tb_v2214 = "    int large, cls, in_avail, np;  // np: внутри нет адресов (числа, тексты) — обход туда не смотрит\n"; *(const char * *)tb_grow(v_lines) = tb_v2214; }
    { const char * tb_v2215 = "    unsigned char *fl;             // по байту на блок: 1 — занят, 2 — нужен (найден при обходе)\n"; *(const char * *)tb_grow(v_lines) = tb_v2215; }
