    { const char * tb_v2616 = "    // следующий обход — когда новой памяти станет вдвое больше нужной\n"; *(const char * *)tb_grow(v_lines) = tb_v2616; }
    { const char * tb_v2617 = "    // если мусора почти не нашлось (программа копит данные), следующий обход — ещё позже\n"; *(const char * *)tb_grow(v_lines) = tb_v2617; }
    { const char * tb_v2618 = "    // если мусора почти не нашлось (программа копит данные) два раза подряд — ещё реже (×8),\n"; *(const char * *)tb_grow(v_lines) = tb_v2618; }
    { const char * tb_v2619 = "    // но лишней памяти сверх «вдвое» не больше 512 МБ\n"; *(const char * *)tb_grow(v_lines) = tb_v2619; }
