    { const char * tb_v2630 = "// начало программы: top — адрес в кадре main, выше всех кадров программы\n"; *(const char * *)tb_grow(v_lines) = tb_v2630; }
    { const char * tb_v2631 = "// main программы зовём через этот шаг (не встраивается): её переменные точно ниже tb_top\n"; *(const char * *)tb_grow(v_lines) = tb_v2631; }
