    { const char * tb_v2713 = "// ---------- list bool: по одному биту на элемент (в 8 раз меньше памяти) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2713; }
    { const char * tb_v2714 = "// тот же tb_list: len и cap — в битах, size = 0, data — слова по 64 бита\n"; *(const char * *)tb_grow(v_lines) = tb_v2714; }
    { const char * tb_v2715 = "TB_API tb_list *tb_bits_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2715; }
    { const char * tb_v2716 = "    tb_list *l = tb_mem(sizeof(tb_list));\n"; *(const char * *)tb_grow(v_lines) = tb_v2716; }
    { const char * tb_v2717 = "    l->len = 0; l->cap = 64; l->size = 0; l->data = tb_mem_np(8);\n"; *(const char * *)tb_grow(v_lines) = tb_v2717; }
