    { const char * tb_v2733 = "    if (TB_RARE((unsigned long long)i >= (unsigned long long)l->len)) tb_crash(line, \"номер за пределами списка\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2733; }
    { const char * tb_v2734 = "    return TB_BIT(l, i);\n"; *(const char * *)tb_grow(v_lines) = tb_v2734; }
    { const char * tb_v2735 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2735; }
