    { const char * tb_v3273 = "TB_API const char *tb_date_now(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3273; }
    { const char * tb_v3274 = "    time_t t = time(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3274; }
