    { const char * tb_v3658 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3658; }
    { const char * tb_v3659 = "// список целиком: сам список, его память и (texts) тексты-элементы\n"; *(const char * *)tb_grow(v_lines) = tb_v3659; }
    { const char * tb_v3660 = "TB_API void tb_export_list(tb_list *l, int texts) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3660; }
