    { const char * tb_v3704 = "    long long tag = TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v3704; }
    { const char * tb_v3705 = "    while (d->slots[i] != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3705; }
    { const char * tb_v3706 = "        long long sl = d->slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3706; }
    { const char * tb_v3707 = "        // метка хеша совпала — только тогда сравниваем сами ключи (текст — дорого)\n"; *(const char * *)tb_grow(v_lines) = tb_v3707; }
