    { const char * tb_v3714 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3714; }
    { const char * tb_v3715 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3715; }
    { const char * tb_v3716 = "// память для таблиц dict — там же, где лежат его ключи (временная или обычная)\n"; *(const char * *)tb_grow(v_lines) = tb_v3716; }
