    { const char * tb_v3726 = "        if (!(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v3726; }
    { const char * tb_v3727 = "        d->pos = 0; d->npos = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3727; }
    { const char * tb_v3728 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3728; }
    { const char * tb_v3729 = "    d->nslots = nslots;\n"; *(const char * *)tb_grow(v_lines) = tb_v3729; }
