    { const char * tb_v3824 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3824; }
    { const char * tb_v3825 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v3825; }
