    { const char * tb_v3883 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3883; }
    { const char * tb_v3884 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v3884; }
    { const char * tb_v3885 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3885; }
