    { const char * tb_v3894 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3894; }
    { const char * tb_v3895 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v3895; }
    { const char * tb_v3896 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3896; }
