    { const char * tb_v3901 = "TB_API void tb_service_start(tb_task *t, void *(*run)(void *), void *arg) { tb_task_start(t, run, arg); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3901; }
    { const char * tb_v3902 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v3902; }
    { const char * tb_v3903 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3903; }
    { const char * tb_v3904 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3904; }
