    { const char * tb_v3929 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v3929; }
    { const char * tb_v3930 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3930; }
    { const char * tb_v3931 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3931; }
    { const char * tb_v3932 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3932; }
    { const char * tb_v3933 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v3933; }
    { const char * tb_v3934 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v3934; }
    { const char * tb_v3935 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v3935; }
    { const char * tb_v3936 = "TB_API pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3936; }
    { const char * tb_v3937 = "TB_API int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3937; }
    { const char * tb_v3938 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v3938; }
    { const char * tb_v3939 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v3939; }
    { const char * tb_v3940 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3940; }
    { const char * tb_v3941 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3941; }
    { const char * tb_v3942 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3942; }
    { const char * tb_v3943 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3943; }
    { const char * tb_v3944 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v3944; }
    { const char * tb_v3945 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v3945; }
    { const char * tb_v3946 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3946; }
    { const char * tb_v3947 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3947; }
    { const char * tb_v3948 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3948; }
    { const char * tb_v3949 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3949; }
    { const char * tb_v3950 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3950; }
    { const char * tb_v3951 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3951; }
    { const char * tb_v3952 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3952; }
    { const char * tb_v3953 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3953; }
    { const char * tb_v3954 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v3954; }
    { const char * tb_v3955 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v3955; }
    { const char * tb_v3956 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3956; }
    { const char * tb_v3957 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3957; }
    { const char * tb_v3958 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3958; }
    { const char * tb_v3959 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3959; }
    { const char * tb_v3960 = "TB_API volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3960; }
    { const char * tb_v3961 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3961; }
    { const char * tb_v3962 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3962; }
    { const char * tb_v3963 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3963; }
    { const char * tb_v3964 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v3964; }
    { const char * tb_v3965 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v3965; }
    { const char * tb_v3966 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3966; }
    { const char * tb_v3967 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3967; }
    { const char * tb_v3968 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3968; }
    { const char * tb_v3969 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v3969; }
    { const char * tb_v3970 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3970; }
    { const char * tb_v3971 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v3971; }
    { const char * tb_v3972 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3972; }
    { const char * tb_v3973 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3973; }
    { const char * tb_v3974 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v3974; }
    { const char * tb_v3975 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v3975; }
    { const char * tb_v3976 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v3976; }
    { const char * tb_v3977 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v3977; }
    { const char * tb_v3978 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3978; }
    { const char * tb_v3979 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v3979; }
    { const char * tb_v3980 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3980; }
    { const char * tb_v3981 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3981; }
    { const char * tb_v3982 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3982; }
    { const char * tb_v3983 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3983; }
    { const char * tb_v3984 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v3984; }
    { const char * tb_v3985 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3985; }
    { const char * tb_v3986 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3986; }
    { const char * tb_v3987 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3987; }
    { const char * tb_v3988 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3988; }
    { const char * tb_v3989 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3989; }
    { const char * tb_v3990 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3990; }
    { const char * tb_v3991 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v3991; }
    { const char * tb_v3992 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v3992; }
    { const char * tb_v3993 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3993; }
    { const char * tb_v3994 = "    if (n == 1) { work(job); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3994; }
    { const char * tb_v3995 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v3995; }
    { const char * tb_v3996 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3996; }
    { const char * tb_v3997 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3997; }
    { const char * tb_v3998 = "        for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3998; }
    { const char * tb_v3999 = "            if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3999; }
    { const char * tb_v4000 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v4000; }
    { const char * tb_v4001 = "        for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4001; }
    { const char * tb_v4002 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4002; }
    { const char * tb_v4003 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4003; }
    { const char * tb_v4004 = "    while (tb_pool_n < n - 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4004; }
    { const char * tb_v4005 = "        pthread_t th;\n"; *(const char * *)tb_grow(v_lines) = tb_v4005; }
    { const char * tb_v4006 = "        if (tb_thread_create(&th, tb_pool_loop, (void *)(long long)tb_pool_n) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4006; }
    { const char * tb_v4007 = "        pthread_detach(th);\n"; *(const char * *)tb_grow(v_lines) = tb_v4007; }
    { const char * tb_v4008 = "        tb_pool_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4008; }
    { const char * tb_v4009 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4009; }
    { const char * tb_v4010 = "    pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v4010; }
    { const char * tb_v4011 = "    tb_pool_work = work; tb_pool_job = job; tb_pool_want = n - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4011; }
    { const char * tb_v4012 = "    __atomic_store_n(&tb_pool_left, n - 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v4012; }
    { const char * tb_v4013 = "    __atomic_add_fetch(&tb_gthreads, n - 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v4013; }
    { const char * tb_v4014 = "    __atomic_add_fetch(&tb_pool_gen, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v4014; }
    { const char * tb_v4015 = "    pthread_cond_broadcast(&tb_pool_go);\n"; *(const char * *)tb_grow(v_lines) = tb_v4015; }
    { const char * tb_v4016 = "    pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v4016; }
    { const char * tb_v4017 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v4017; }
    { const char * tb_v4018 = "    if (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4018; }
    { const char * tb_v4019 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v4019; }
    { const char * tb_v4020 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v4020; }
    { const char * tb_v4021 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v4021; }
    { const char * tb_v4022 = "        while (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) pthread_cond_wait(&tb_pool_end, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v4022; }
    { const char * tb_v4023 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v4023; }
    { const char * tb_v4024 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4024; }
    { const char * tb_v4025 = "    __atomic_store_n(&tb_pool_busy, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v4025; }
    { const char * tb_v4026 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4026; }
    { const char * tb_v4027 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4027; }
    { const char * tb_v4028 = "TB_API long long tb_par_step(long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4028; }
    { const char * tb_v4029 = "    long long s = total / ((long long)tb_cores() * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v4029; }
    { const char * tb_v4030 = "    return s < 1 ? 1 : s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4030; }
    { const char * tb_v4031 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4031; }
    { const char * tb_v4032 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v4032; }
    { const char * tb_v4033 = "// ---------- биты, адреса, порты, замки (danger и lock) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4033; }
    { const char * tb_v4034 = "TB_INL long long tb_band(long long a, long long b) { return a & b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4034; }
    { const char * tb_v4035 = "TB_INL long long tb_bor(long long a, long long b) { return a | b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4035; }
