    { const char * tb_v4094 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4094; }
    { const char * tb_v4095 = "TB_API void tb_mem_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4095; }
    { const char * tb_v4096 = "    long long n = 0, bytes = 0; int first = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4096; }
    { const char * tb_v4097 = "    for (long long i = 0; i < tb_mem_n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v4097; }
    { const char * tb_v4098 = "        if (tb_mem_all[i].live) { if (!n) first = tb_mem_all[i].line; n++; bytes += (long long)tb_mem_all[i].n; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4098; }
    { const char * tb_v4099 = "    if (n && tb_mem_check) fprintf(stderr, \"TB_MEM_CHECK: не освобождено блоков %lld (%lld байт), первый из new_mem в строке %d\\n\", n, bytes, first);\n"; *(const char * *)tb_grow(v_lines) = tb_v4099; }
    { const char * tb_v4100 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4100; }
    { const char * tb_v4101 = "// TB_MEM_CHECK: можно ли трогать байты [a, a + n)\n"; *(const char * *)tb_grow(v_lines) = tb_v4101; }
    { const char * tb_v4102 = "static void tb_mem_touch(uintptr_t a, uint64_t n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4102; }
    { const char * tb_v4103 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4103; }
    { const char * tb_v4104 = "    tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v4104; }
    { const char * tb_v4105 = "    for (long long i = 0; i < tb_mem_n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4105; }
    { const char * tb_v4106 = "        tb_memb *b = &tb_mem_all[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v4106; }
    { const char * tb_v4107 = "        uintptr_t lo = b->a - sizeof(tb_memh), hi = b->a + b->n + TB_MEM_GUARD;\n"; *(const char * *)tb_grow(v_lines) = tb_v4107; }
    { const char * tb_v4108 = "        if (a + n <= lo || a >= hi) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v4108; }
    { const char * tb_v4109 = "        if (!b->live) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4109; }
    { const char * tb_v4110 = "            char buf[160];\n"; *(const char * *)tb_grow(v_lines) = tb_v4110; }
    { const char * tb_v4111 = "            snprintf(buf, sizeof buf, \"эта память уже освобождена: free_mem в строке %d\", b->fline);\n"; *(const char * *)tb_grow(v_lines) = tb_v4111; }
    { const char * tb_v4112 = "            tb_mem_die(line, buf, b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v4112; }
    { const char * tb_v4113 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4113; }
    { const char * tb_v4114 = "        if (a < b->a || a + n > b->a + b->n) tb_mem_die(line, \"чтение или запись за краем блока\", b->line);\n"; *(const char * *)tb_grow(v_lines) = tb_v4114; }
    { const char * tb_v4115 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4115; }
    { const char * tb_v4116 = "    tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v4116; }
    { const char * tb_v4117 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4117; }
    { const char * tb_v4118 = "static tb_memb *tb_mem_find(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4118; }
    { const char * tb_v4119 = "    for (long long i = tb_mem_n - 1; i >= 0; i--) if (tb_mem_all[i].a == a) return &tb_mem_all[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v4119; }
    { const char * tb_v4120 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4120; }
    { const char * tb_v4121 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4121; }
    { const char * tb_v4122 = "// чтение и запись по адресу: volatile — компилятор C не выкинет и не переставит их\n"; *(const char * *)tb_grow(v_lines) = tb_v4122; }
    { const char * tb_v4123 = "#define TB_TOUCH(a, n) if (TB_RARE(tb_memchk())) tb_mem_touch((uintptr_t)(a), (n), line)\n"; *(const char * *)tb_grow(v_lines) = tb_v4123; }
    { const char * tb_v4124 = "TB_INL long long tb_rd8(long long a, int line) { TB_TOUCH(a, 1); return *(volatile uint8_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4124; }
    { const char * tb_v4125 = "TB_INL long long tb_rd16(long long a, int line) { TB_TOUCH(a, 2); return *(volatile uint16_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4125; }
    { const char * tb_v4126 = "TB_INL long long tb_rd32(long long a, int line) { TB_TOUCH(a, 4); return *(volatile uint32_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4126; }
    { const char * tb_v4127 = "TB_INL long long tb_rd64(long long a, int line) { TB_TOUCH(a, 8); return (long long)*(volatile uint64_t *)(uintptr_t)a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4127; }
    { const char * tb_v4128 = "TB_INL void tb_wr8(long long a, long long v, int line) { TB_TOUCH(a, 1); *(volatile uint8_t *)(uintptr_t)a = (uint8_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4128; }
