    { const char * tb_v4131 = "TB_INL void tb_wr64(long long a, long long v, int line) { TB_TOUCH(a, 8); *(volatile uint64_t *)(uintptr_t)a = (uint64_t)v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4131; }
    { const char * tb_v4132 = "TB_INL long long tb_addr_of(tb_list *l) { return (long long)(uintptr_t)l->data; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4132; }
    { const char * tb_v4133 = "// new_mem(байт): новый блок, заполнен нулями; адрес — число. Может не получиться (нет памяти)\n"; *(const char * *)tb_grow(v_lines) = tb_v4133; }
    { const char * tb_v4134 = "TB_API long long tb_new_mem(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4134; }
    { const char * tb_v4135 = "    if (n <= 0) { tb_err = \"new_mem: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4135; }
    { const char * tb_v4136 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"new_mem: слишком большой блок\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4136; }
    { const char * tb_v4137 = "    int chk = tb_memchk();\n"; *(const char * *)tb_grow(v_lines) = tb_v4137; }
