    { const char * tb_v4152 = "        if (tb_mem_n == tb_mem_cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4152; }
    { const char * tb_v4153 = "            long long nc = tb_mem_cap ? tb_mem_cap * 2 : 256;\n"; *(const char * *)tb_grow(v_lines) = tb_v4153; }
    { const char * tb_v4154 = "            tb_memb *all = realloc(tb_mem_all, (size_t)nc * sizeof(tb_memb));\n"; *(const char * *)tb_grow(v_lines) = tb_v4154; }
    { const char * tb_v4155 = "            if (!all) tb_mem_die(line, \"не хватило памяти\", 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4155; }
    { const char * tb_v4156 = "            tb_mem_all = all; tb_mem_cap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v4156; }
    { const char * tb_v4157 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4157; }
    { const char * tb_v4158 = "        tb_memb b = { (uintptr_t)p, (uint64_t)n, 1, line, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4158; }
    { const char * tb_v4159 = "        tb_mem_all[tb_mem_n++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v4159; }
    { const char * tb_v4160 = "        tb_mem_unlock();\n"; *(const char * *)tb_grow(v_lines) = tb_v4160; }
    { const char * tb_v4161 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4161; }
