    { const char * tb_v4181 = "    tb_memh *h = (tb_memh *)(uintptr_t)a - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4181; }
    { const char * tb_v4182 = "    if (h->magic == TB_MEM_DEAD) { snprintf(buf, sizeof buf, \"%s: блок уже освобождён\", who); tb_crash(line, buf); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4182; }
    { const char * tb_v4183 = "    if (h->magic != TB_MEM_LIVE) { snprintf(buf, sizeof buf, \"%s: это не адрес из new_mem или блок уже освобождён (точнее покажет TB_MEM_CHECK=1)\", who); tb_crash(line, buf); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4183; }
    { const char * tb_v4184 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v4184; }
    { const char * tb_v4185 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4185; }
    { const char * tb_v4186 = "// TB_MEM_CHECK: блок не отдаётся обратно, а помечается — чтобы поймать чтение после free_mem\n"; *(const char * *)tb_grow(v_lines) = tb_v4186; }
    { const char * tb_v4187 = "static void tb_mem_bury(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4187; }
    { const char * tb_v4188 = "    tb_mem_lock();\n"; *(const char * *)tb_grow(v_lines) = tb_v4188; }
