    { const char * tb_v5542 = "TB_API long long tb_image_w(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].w : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5542; }
    { const char * tb_v5543 = "TB_API long long tb_image_h(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].h : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5543; }
    { const char * tb_v5544 = "// ---------- шрифты TTF: свой чтец (таблицы glyf, без чужих библиотек) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5544; }
    { const char * tb_v5545 = "// Буква рисуется на процессоре один раз в маленькую картинку с прозрачностью (сглаживание),\n"; *(const char * *)tb_grow(v_lines) = tb_v5545; }
    { const char * tb_v5546 = "// дальше её рисуют и видеокарта, и процессор одинаково: точка = (цвет * a + фон * (255 - a)) / 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v5546; }
    { const char * tb_v5547 = "typedef struct { unsigned char *d; size_t n; uint32_t glyf, loca, hmtx, cmap; int upem, locfmt, nglyphs, nhm, asc, desc, cfmt; } tb_font_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v5547; }
    { const char * tb_v5548 = "TB_API tb_font_t *tb_fonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5548; }
    { const char * tb_v5549 = "TB_API int tb_nfonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5549; }
    { const char * tb_v5550 = "static unsigned tb_u16(const tb_font_t *f, size_t o) { return o + 2 <= f->n ? (unsigned)(f->d[o] << 8 | f->d[o + 1]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5550; }
    { const char * tb_v5551 = "static int tb_s16(const tb_font_t *f, size_t o) { return (int16_t)tb_u16(f, o); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5551; }
    { const char * tb_v5552 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5552; }
    { const char * tb_v5553 = "static uint32_t tb_ttf_table(const tb_font_t *f, size_t base, const char *tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5553; }
    { const char * tb_v5554 = "    unsigned n = tb_u16(f, base + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5554; }
    { const char * tb_v5555 = "    for (unsigned i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5555; }
    { const char * tb_v5556 = "        size_t e = base + 12 + 16 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v5556; }
    { const char * tb_v5557 = "        if (e + 16 <= f->n && memcmp(f->d + e, tag, 4) == 0) return tb_u32(f, e + 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v5557; }
    { const char * tb_v5558 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5558; }
    { const char * tb_v5559 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5559; }
    { const char * tb_v5560 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5560; }
    { const char * tb_v5561 = "TB_API void tb_gpu_blend_probe(void);   // TB_GPU_CHECK: проба смешивания букв (ниже)\n"; *(const char * *)tb_grow(v_lines) = tb_v5561; }
    { const char * tb_v5562 = "TB_API long long tb_load_font(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5562; }
    { const char * tb_v5563 = "    FILE *fp = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5563; }
    { const char * tb_v5564 = "    if (!fp) { tb_err = tb_cat(\"нет такого файла шрифта: \", path); return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5564; }
    { const char * tb_v5565 = "    fseek(fp, 0, SEEK_END); long sz = ftell(fp); fseek(fp, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v5565; }
    { const char * tb_v5566 = "    unsigned char *d = sz > 12 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5566; }
    { const char * tb_v5567 = "    if (!d || fread(d, 1, (size_t)sz, fp) != (size_t)sz) { fclose(fp); free(d); tb_err = \"не могу прочитать файл шрифта\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5567; }
    { const char * tb_v5568 = "    fclose(fp);\n"; *(const char * *)tb_grow(v_lines) = tb_v5568; }
    { const char * tb_v5569 = "    tb_font_t f = { d, (size_t)sz };\n"; *(const char * *)tb_grow(v_lines) = tb_v5569; }
    { const char * tb_v5570 = "    size_t base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5570; }
    { const char * tb_v5571 = "    if (memcmp(d, \"ttcf\", 4) == 0) base = tb_u32(&f, 12);   // сборник шрифтов (.ttc): берём первый\n"; *(const char * *)tb_grow(v_lines) = tb_v5571; }
    { const char * tb_v5572 = "    uint32_t head = tb_ttf_table(&f, base, \"head\"), maxp = tb_ttf_table(&f, base, \"maxp\"), hhea = tb_ttf_table(&f, base, \"hhea\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5572; }
    { const char * tb_v5573 = "    f.glyf = tb_ttf_table(&f, base, \"glyf\"); f.loca = tb_ttf_table(&f, base, \"loca\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5573; }
    { const char * tb_v5574 = "    f.hmtx = tb_ttf_table(&f, base, \"hmtx\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5574; }
    { const char * tb_v5575 = "    uint32_t cmap = tb_ttf_table(&f, base, \"cmap\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5575; }
    { const char * tb_v5576 = "    if (!f.glyf || !f.loca) { free(d); tb_err = \"этот шрифт не TrueType (контуры CFF/OTF пока не читаю): возьми .ttf\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5576; }
    { const char * tb_v5577 = "    if (!head || !maxp || !hhea || !f.hmtx || !cmap) { free(d); tb_err = \"шрифт сломан: нет нужных таблиц\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5577; }
    { const char * tb_v5578 = "    f.upem = (int)tb_u16(&f, head + 18); f.locfmt = tb_s16(&f, head + 50);\n"; *(const char * *)tb_grow(v_lines) = tb_v5578; }
    { const char * tb_v5579 = "    f.nglyphs = (int)tb_u16(&f, maxp + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5579; }
    { const char * tb_v5580 = "    f.asc = tb_s16(&f, hhea + 4); f.desc = tb_s16(&f, hhea + 6); f.nhm = (int)tb_u16(&f, hhea + 34);\n"; *(const char * *)tb_grow(v_lines) = tb_v5580; }
    { const char * tb_v5581 = "    if (f.upem <= 0 || f.nhm <= 0 || f.asc - f.desc <= 0) { free(d); tb_err = \"шрифт сломан: размеры\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5581; }
    { const char * tb_v5582 = "    // буквы → номера глифов: Unicode-таблица формата 12 (все буквы) или 4 (до U+FFFF)\n"; *(const char * *)tb_grow(v_lines) = tb_v5582; }
    { const char * tb_v5583 = "    unsigned nt = tb_u16(&f, cmap + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v5583; }
    { const char * tb_v5584 = "    int best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5584; }
    { const char * tb_v5585 = "    for (unsigned i = 0; i < nt; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5585; }
    { const char * tb_v5586 = "        size_t e = cmap + 4 + 8 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v5586; }
    { const char * tb_v5587 = "        unsigned pid = tb_u16(&f, e), eid = tb_u16(&f, e + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v5587; }
    { const char * tb_v5588 = "        uint32_t off = cmap + tb_u32(&f, e + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5588; }
    { const char * tb_v5589 = "        unsigned fmt = tb_u16(&f, off);\n"; *(const char * *)tb_grow(v_lines) = tb_v5589; }
    { const char * tb_v5590 = "        int score = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5590; }
    { const char * tb_v5591 = "        if (fmt == 12 && (pid == 0 || (pid == 3 && eid == 10))) score = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v5591; }
    { const char * tb_v5592 = "        else if (fmt == 4 && (pid == 0 || (pid == 3 && eid == 1))) score = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v5592; }
    { const char * tb_v5593 = "        if (score > best) { best = score; f.cmap = off; f.cfmt = (int)fmt; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5593; }
    { const char * tb_v5594 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5594; }
    { const char * tb_v5595 = "    if (!best) { free(d); tb_err = \"в шрифте нет таблицы букв Unicode\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5595; }
