    { const char * tb_v5879 = "    return (long long)floor(best + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v5879; }
    { const char * tb_v5880 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5880; }
    { const char * tb_v5881 = "TB_API void tb_draw_image_a(long long id, long long x, long long y);\n"; *(const char * *)tb_grow(v_lines) = tb_v5881; }
    { const char * tb_v5882 = "TB_API void tb_draw_font(long long fi, long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5882; }
    { const char * tb_v5883 = "    if (!tb_px || fi < 0 || fi >= tb_nfonts || size <= 0 || size > 1000) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5883; }
    { const char * tb_v5884 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v5884; }
    { const char * tb_v5885 = "    double scale = (double)size / f->upem, pen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5885; }
    { const char * tb_v5886 = "    long long base = y + tb_font_base(f, size), lh = size * 5 / 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v5886; }
    { const char * tb_v5887 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v5887; }
    { const char * tb_v5888 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5888; }
    { const char * tb_v5889 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5889; }
    { const char * tb_v5890 = "        if (u == '\\n') { pen = 0; base += lh; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5890; }
    { const char * tb_v5891 = "        unsigned g = tb_ttf_glyph(f, u);\n"; *(const char * *)tb_grow(v_lines) = tb_v5891; }
    { const char * tb_v5892 = "        long long gx = x + (long long)floor(pen + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v5892; }
    { const char * tb_v5893 = "        pen += tb_ttf_adv(f, g) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v5893; }
    { const char * tb_v5894 = "        if (u == ' ' || gx >= tb_gw || base - 2 * size > tb_gh) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v5894; }
    { const char * tb_v5895 = "        tb_gcache *gc = tb_glyph_img((int)fi, g, (int)size, (uint32_t)c & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v5895; }
    { const char * tb_v5896 = "        if (gc->img >= 0) tb_draw_image_a(gc->img, gx + gc->left, base + gc->top);\n"; *(const char * *)tb_grow(v_lines) = tb_v5896; }
    { const char * tb_v5897 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5897; }
    { const char * tb_v5898 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5898; }
    { const char * tb_v5899 = "// ---------- рисование на видеокарте (GPU) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5899; }
    { const char * tb_v5900 = "// Кадр не рисуется точками на процессоре: каждая фигура записывается как «экземпляр»\n"; *(const char * *)tb_grow(v_lines) = tb_v5900; }
    { const char * tb_v5901 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v5901; }
    { const char * tb_v5902 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v5902; }
    { const char * tb_v5903 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v5903; }
    { const char * tb_v5904 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v5904; }
    { const char * tb_v5905 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v5905; }
    { const char * tb_v5906 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v5906; }
    { const char * tb_v5907 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v5907; }
    { const char * tb_v5908 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5908; }
    { const char * tb_v5909 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5909; }
    { const char * tb_v5910 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5910; }
    { const char * tb_v5911 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5911; }
    { const char * tb_v5912 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v5912; }
    { const char * tb_v5913 = "// она лежит в tb_gplane[набор * TB_GI_CAP + номер фигуры], а в m — 2 | (это место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v5913; }
    { const char * tb_v5914 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v5914; }
    { const char * tb_v5915 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5915; }
    { const char * tb_v5916 = "// 3D с картинкой (mesh_image): у треугольника ещё запись текстуры — плоскости u·W и v·W (по 64 бита)\n"; *(const char * *)tb_grow(v_lines) = tb_v5916; }
    { const char * tb_v5917 = "// и сама картинка; номер записи — в pad его плоскости глубины, а в m ещё бит 29\n"; *(const char * *)tb_grow(v_lines) = tb_v5917; }
    { const char * tb_v5918 = "typedef struct { int64_t au, bu, cu, av, bv, cv; uint32_t off, w, h, pad; } tb_gtex_t;   // 64 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v5918; }
    { const char * tb_v5919 = "enum { TB_GT_CAP = 16384 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5919; }
    { const char * tb_v5920 = "TB_API tb_gtex_t *tb_gtex = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5920; }
    { const char * tb_v5921 = "TB_API int tb_gtn = 0, tb_gpu_tex = 0;   // записей в текущем наборе; видеокарта умеет картинки на сетках\n"; *(const char * *)tb_grow(v_lines) = tb_v5921; }
    { const char * tb_v5922 = "// «новые» треугольники 3D (свет по углам, тени, туман, прозрачность — см. tb_lit_px): у каждого запись — W трёх углов,\n"; *(const char * *)tb_grow(v_lines) = tb_v5922; }
    { const char * tb_v5923 = "// флаги (1 — тени, 2 — туман, прозрачность << 8), по 12 чисел на угол (значение × W), туман, картинка, карта теней.\n"; *(const char * *)tb_grow(v_lines) = tb_v5923; }
    { const char * tb_v5924 = "// Номер записи — в pad плоскости глубины, а в m — бит 28 (и бит 27 у прозрачного)\n"; *(const char * *)tb_grow(v_lines) = tb_v5924; }
    { const char * tb_v5925 = "typedef struct { int32_t w[3], flags; int32_t v[3][12]; int32_t fogc, fogn, fogf, tex, smn, smbase, pad0, pad1; } tb_glit_t;   // 192 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v5925; }
    { const char * tb_v5926 = "enum { TB_GL_CAP = 16384, TB_LV = 11, TB_SM_N = 1024 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5926; }
    { const char * tb_v5927 = "TB_API tb_glit_t *tb_glit = 0;           // записи всех наборов (видны видеокарте; появляются при первом таком треугольнике)\n"; *(const char * *)tb_grow(v_lines) = tb_v5927; }
    { const char * tb_v5928 = "TB_API int tb_gln = 0, tb_gpu_lit = 0;   // записей в текущем наборе; видеокарта умеет такие треугольники\n"; *(const char * *)tb_grow(v_lines) = tb_v5928; }
    { const char * tb_v5929 = "TB_API void tb_gpu_lit_mem(int shadow);  // своя у каждой системы: память записей (0) или карт теней (1)\n"; *(const char * *)tb_grow(v_lines) = tb_v5929; }
    { const char * tb_v5930 = "TB_API void tb_gpu_tril(const long long *t, long long c, const uint32_t *pl, const tb_glit_t *L, const tb_gtex_t *tx);\n"; *(const char * *)tb_grow(v_lines) = tb_v5930; }
    { const char * tb_v5931 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v5931; }
    { const char * tb_v5932 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v5932; }
    { const char * tb_v5933 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v5933; }
    { const char * tb_v5934 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5934; }
    { const char * tb_v5935 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v5935; }
    { const char * tb_v5936 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v5936; }
    { const char * tb_v5937 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v5937; }
    { const char * tb_v5938 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v5938; }
    { const char * tb_v5939 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v5939; }
    { const char * tb_v5940 = "typedef struct { int32_t r[16]; } tb_grec;   // 4 строки: поворот × 2^30 и сдвиг × 4096 (3), свет в сетке (x, y, z × 2^14, фон × 256; фон -1 — без света)\n"; *(const char * *)tb_grow(v_lines) = tb_v5940; }
    { const char * tb_v5941 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5941; }
    { const char * tb_v5942 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5942; }
    { const char * tb_v5943 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v5943; }
    { const char * tb_v5944 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v5944; }
    { const char * tb_v5945 = "TB_API int tb_mesh_gdirty = 1;         // сетки поменялись: перед рисованием залить заново\n"; *(const char * *)tb_grow(v_lines) = tb_v5945; }
    { const char * tb_v5946 = "TB_API long long tb_gbatch = 1;        // номер текущей пачки (растёт после каждой отдачи видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5946; }
    { const char * tb_v5947 = "typedef struct { float size[2]; int32_t tbase, ntri, rbase, f, gw, gh, cull; } tb_gpc;   // постоянные шейдера сеток\n"; *(const char * *)tb_grow(v_lines) = tb_v5947; }
    { const char * tb_v5948 = "TB_API long long tb_mesh_pack(int32_t *dst);   // все сетки подряд для видеокарты (dst = 0: только размер)\n"; *(const char * *)tb_grow(v_lines) = tb_v5948; }
    { const char * tb_v5949 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc);   // постоянные для фигуры m = 3\n"; *(const char * *)tb_grow(v_lines) = tb_v5949; }
    { const char * tb_v5950 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v5950; }
    { const char * tb_v5951 = "enum { TB_GSLOTS = 3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5951; }
    { const char * tb_v5952 = "TB_API int tb_gslot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5952; }
    { const char * tb_v5953 = "TB_API uint32_t *tb_gpu_back = 0;      // TB_GPU_CHECK: кадр, прочитанный обратно с видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v5953; }
    { const char * tb_v5954 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0, tb_gpu_shskip = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5954; }
    { const char * tb_v5955 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v5955; }
    { const char * tb_v5956 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v5956; }
    { const char * tb_v5957 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5957; }
    { const char * tb_v5958 = "TB_API int tb_gpu_resize(int ow, int oh);   // окно поменяло размер\n"; *(const char * *)tb_grow(v_lines) = tb_v5958; }
    { const char * tb_v5959 = "// окно можно тянуть мышью, если программа спросила его размер (window_w, window_h)\n"; *(const char * *)tb_grow(v_lines) = tb_v5959; }
    { const char * tb_v5960 = "TB_API int tb_resizable = 0, tb_new_w = 0, tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5960; }
    { const char * tb_v5961 = "// несколько окон (1.3): номер текущего окна, сколько мест занято, ручка каждого окна в системе\n"; *(const char * *)tb_grow(v_lines) = tb_v5961; }
    { const char * tb_v5962 = "#define TB_WMAX 16\n"; *(const char * *)tb_grow(v_lines) = tb_v5962; }
    { const char * tb_v5963 = "TB_API int tb_wcur = 0, tb_wn = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5963; }
    { const char * tb_v5964 = "TB_API uintptr_t tb_whand[TB_WMAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v5964; }
    { const char * tb_v5965 = "TB_API int tb_wfind(uintptr_t h);\n"; *(const char * *)tb_grow(v_lines) = tb_v5965; }
    { const char * tb_v5966 = "TB_API void tb_wswitch(int i);\n"; *(const char * *)tb_grow(v_lines) = tb_v5966; }
    { const char * tb_v5967 = "TB_API void tb_wmark_closed(int i);\n"; *(const char * *)tb_grow(v_lines) = tb_v5967; }
    { const char * tb_v5968 = "// полный экран и мышь для шутера (1.3): сдвиг мыши с прошлого mouse_dx/mouse_dy, мышь захвачена\n"; *(const char * *)tb_grow(v_lines) = tb_v5968; }
    { const char * tb_v5969 = "TB_API double tb_mdx = 0, tb_mdy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5969; }
    { const char * tb_v5970 = "TB_API int tb_mlock = 0, tb_mseen = 0, tb_mwarp = 0, tb_cursor_prog = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5970; }
    { const char * tb_v5971 = "TB_API void tb_gfx_fullscreen(int on);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v5971; }
    { const char * tb_v5972 = "TB_API void tb_gfx_lock(int on);\n"; *(const char * *)tb_grow(v_lines) = tb_v5972; }
    { const char * tb_v5973 = "// мышь в точке (x, y) окна: копим сдвиг. Захвачена — меряем от середины окна, мышь потом вернётся туда\n"; *(const char * *)tb_grow(v_lines) = tb_v5973; }
    { const char * tb_v5974 = "TB_API void tb_mouse_at(int x, int y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5974; }
    { const char * tb_v5975 = "    if (tb_mlock) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5975; }
    { const char * tb_v5976 = "        int cx = tb_gw / 2, cy = tb_gh / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v5976; }
    { const char * tb_v5977 = "        if (x == cx && y == cy) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5977; }
    { const char * tb_v5978 = "        tb_mdx += x - cx; tb_mdy += y - cy; tb_mwarp = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5978; }
    { const char * tb_v5979 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5979; }
    { const char * tb_v5980 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5980; }
    { const char * tb_v5981 = "    if (tb_mseen) { tb_mdx += x - tb_mx; tb_mdy += y - tb_my; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5981; }
    { const char * tb_v5982 = "    tb_mseen = 1; tb_mx = x; tb_my = y;\n"; *(const char * *)tb_grow(v_lines) = tb_v5982; }
    { const char * tb_v5983 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5983; }
    { const char * tb_v5984 = "TB_API int tb_sharp = 0;       // window_sharp(): окно в настоящих точках экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v5984; }
    { const char * tb_v5985 = "TB_API double tb_sc = 1;        // во сколько раз точек больше (Retina — 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v5985; }
    { const char * tb_v5986 = "TB_API void tb_gfx_resizable(void);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v5986; }
    { const char * tb_v5987 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v5987; }
    { const char * tb_v5988 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5988; }
    { const char * tb_v5989 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5989; }
    { const char * tb_v5990 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v5990; }
    { const char * tb_v5991 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5991; }
    { const char * tb_v5992 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v5992; }
    { const char * tb_v5993 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5993; }
    { const char * tb_v5994 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5994; }
    { const char * tb_v5995 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5995; }
    { const char * tb_v5996 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, \"окно: рисует %s\\n\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v5996; }
    { const char * tb_v5997 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5997; }
    { const char * tb_v5998 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5998; }
    { const char * tb_v5999 = "    fprintf(stderr, \"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\", tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v5999; }
    { const char * tb_v6000 = "    if (tb_gpu_shskip) fprintf(stderr, \"TB_GPU_CHECK: кадров со своими шейдерами (не сверялись): %lld\\n\", tb_gpu_shskip);\n"; *(const char * *)tb_grow(v_lines) = tb_v6000; }
    { const char * tb_v6001 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6001; }
    { const char * tb_v6002 = "// ---- gpu func (1.3): шейдеры программы — их собрал компилятор Tachbit из gpu func ----\n"; *(const char * *)tb_grow(v_lines) = tb_v6002; }
    { const char * tb_v6003 = "// У каждого: имя, вид (0 — углы, 1 — точка), функция для процессора, SPIR-V, имена настроек по порядку.\n"; *(const char * *)tb_grow(v_lines) = tb_v6003; }
    { const char * tb_v6004 = "// Metal берёт все шейдеры из одного текста tb_sh_msl. Сетка со своим шейдером рисуется обычными\n"; *(const char * *)tb_grow(v_lines) = tb_v6004; }
    { const char * tb_v6005 = "// дробными числами (не точка в точку с процессором): в пачке это фигура m = 7 — x0 номер записи,\n"; *(const char * *)tb_grow(v_lines) = tb_v6005; }
    { const char * tb_v6006 = "// y0 шейдер углов, x1 шейдер точки, y1 сколько углов; углы сетки лежат в своём буфере видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v6006; }
    { const char * tb_v6007 = "typedef void (*tb_shfn)(float *io);\n"; *(const char * *)tb_grow(v_lines) = tb_v6007; }
    { const char * tb_v6008 = "typedef struct { const char *name; int stage; tb_shfn fn; const uint32_t *spv; size_t bytes; int nsets; char sets[8][32]; } tb_shader_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v6008; }
    { const char * tb_v6009 = "enum { TB_SH_MAX = 64, TB_SHR_CAP = 4096, TB_SHR_N = 48 };\n"; *(const char * *)tb_grow(v_lines) = tb_v6009; }
    { const char * tb_v6010 = "TB_API tb_shader_t tb_shaders[TB_SH_MAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v6010; }
    { const char * tb_v6011 = "TB_API int tb_nshaders = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6011; }
