    { const char * tb_v6013 = "TB_API float *tb_shrecs = 0;          // записи текущего набора: TB_SHR_N чисел на draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v6013; }
    { const char * tb_v6014 = "TB_API int tb_shrn = 0;            // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v6014; }
    { const char * tb_v6015 = "TB_API int tb_sh_frame = 0;        // в кадре была сетка со своим шейдером: TB_GPU_CHECK кадр не сверяет\n"; *(const char * *)tb_grow(v_lines) = tb_v6015; }
    { const char * tb_v6016 = "TB_API void tb_sh_lib(const char *msl) { tb_sh_msl = msl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6016; }
    { const char * tb_v6017 = "TB_API void tb_sh_reg(const char *name, int stage, tb_shfn fn, const uint32_t *spv, size_t bytes, const char *sets) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6017; }
    { const char * tb_v6018 = "    if (tb_nshaders == TB_SH_MAX) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6018; }
    { const char * tb_v6019 = "    tb_shader_t *s = &tb_shaders[tb_nshaders++];\n"; *(const char * *)tb_grow(v_lines) = tb_v6019; }
    { const char * tb_v6020 = "    memset(s, 0, sizeof *s);\n"; *(const char * *)tb_grow(v_lines) = tb_v6020; }
    { const char * tb_v6021 = "    s->name = name; s->stage = stage; s->fn = fn; s->spv = spv; s->bytes = bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v6021; }
    { const char * tb_v6022 = "    for (const char *p = sets; *p && s->nsets < 8;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6022; }
    { const char * tb_v6023 = "        int n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6023; }
    { const char * tb_v6024 = "        while (p[n] && p[n] != ',') n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6024; }
    { const char * tb_v6025 = "        int k = n > 31 ? 31 : n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6025; }
    { const char * tb_v6026 = "        memcpy(s->sets[s->nsets], p, (size_t)k);\n"; *(const char * *)tb_grow(v_lines) = tb_v6026; }
    { const char * tb_v6027 = "        s->sets[s->nsets][k] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6027; }
    { const char * tb_v6028 = "        s->nsets++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6028; }
    { const char * tb_v6029 = "        p += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6029; }
    { const char * tb_v6030 = "        if (*p == ',') p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6030; }
    { const char * tb_v6031 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6031; }
    { const char * tb_v6032 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6032; }
    { const char * tb_v6033 = "TB_API int tb_sh_find(const char *name, int stage) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6033; }
    { const char * tb_v6034 = "    for (int i = 0; i < tb_nshaders; i++) if (tb_shaders[i].stage == stage && strcmp(tb_shaders[i].name, name) == 0) return i;\n"; *(const char * *)tb_grow(v_lines) = tb_v6034; }
    { const char * tb_v6035 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6035; }
    { const char * tb_v6036 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6036; }
    { const char * tb_v6037 = "// свои у каждой системы: готова ли видеокарта; углы сетки в её буфер (старый отдаётся); фигура m = 7 в пачку\n"; *(const char * *)tb_grow(v_lines) = tb_v6037; }
