    { const char * tb_v6040 = "TB_API void tb_gpu_sh_add(void *vb, int cs, int ps, long long nverts);\n"; *(const char * *)tb_grow(v_lines) = tb_v6040; }
    { const char * tb_v6041 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v6041; }
    { const char * tb_v6042 = "// TB_GPU_CHECK: как видеокарта смешивает букву с фоном — таблица из пробы (tb_gpu_blend_probe)\n"; *(const char * *)tb_grow(v_lines) = tb_v6042; }
    { const char * tb_v6043 = "TB_API int tb_blend_cal = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6043; }
