    { const char * tb_v6045 = "TB_API int tb_gpu_probing = 0;   // TB_GPU_CHECK: идёт проба смешивания (tb_gpu_blend_probe), кадры не сверять\n"; *(const char * *)tb_grow(v_lines) = tb_v6045; }
    { const char * tb_v6046 = "TB_API void tb_gpu_compare(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6046; }
    { const char * tb_v6047 = "    if (!tb_gpu_back || tb_gpu_probing) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6047; }
    { const char * tb_v6048 = "    if (tb_sh_frame) { tb_sh_frame = 0; tb_gpu_shskip++; return; }   // свои шейдеры: дробные числа, точка в точку не сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v6048; }
    { const char * tb_v6049 = "    tb_gpu_frames++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6049; }
    { const char * tb_v6050 = "    long long n = (long long)tb_gw * tb_gh, bad = 0, first = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6050; }
    { const char * tb_v6051 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6051; }
    { const char * tb_v6052 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6052; }
    { const char * tb_v6053 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6053; }
    { const char * tb_v6054 = "        tb_gpu_bad++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6054; }
    { const char * tb_v6055 = "        if (tb_gpu_bad <= 5)\n"; *(const char * *)tb_grow(v_lines) = tb_v6055; }
    { const char * tb_v6056 = "            fprintf(stderr, \"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\",\n"; *(const char * *)tb_grow(v_lines) = tb_v6056; }
    { const char * tb_v6057 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v6057; }
    { const char * tb_v6058 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6058; }
    { const char * tb_v6059 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6059; }
    { const char * tb_v6060 = "TB_INL void tb_gpu_add(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, uint32_t c, uint32_t m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6060; }
    { const char * tb_v6061 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6061; }
    { const char * tb_v6062 = "    tb_ginst *g = &tb_gi[tb_gin++];\n"; *(const char * *)tb_grow(v_lines) = tb_v6062; }
    { const char * tb_v6063 = "    g->x0 = (int32_t)x0; g->y0 = (int32_t)y0; g->x1 = (int32_t)x1; g->y1 = (int32_t)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6063; }
    { const char * tb_v6064 = "    g->ox = (int32_t)ox; g->oy = (int32_t)oy; g->c = c; g->m = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v6064; }
    { const char * tb_v6065 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6065; }
    { const char * tb_v6066 = "// прямоугольник: обрезан окном; соседние полоски одного цвета склеиваются (линии, точки по одной)\n"; *(const char * *)tb_grow(v_lines) = tb_v6066; }
    { const char * tb_v6067 = "TB_API void tb_gpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6067; }
    { const char * tb_v6068 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6068; }
    { const char * tb_v6069 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6069; }
    { const char * tb_v6070 = "    uint32_t cc = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v6070; }
    { const char * tb_v6071 = "    if (tb_gin > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6071; }
    { const char * tb_v6072 = "        tb_ginst *g = &tb_gi[tb_gin - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6072; }
    { const char * tb_v6073 = "        if (g->m == 0 && g->c == cc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6073; }
    { const char * tb_v6074 = "            if (g->y0 == y0 && g->y1 == y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6074; }
    { const char * tb_v6075 = "                if (g->x1 == x0) { g->x1 = (int32_t)x1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6075; }
    { const char * tb_v6076 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6076; }
    { const char * tb_v6077 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6077; }
    { const char * tb_v6078 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6078; }
    { const char * tb_v6079 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6079; }
    { const char * tb_v6080 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6080; }
    { const char * tb_v6081 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6081; }
    { const char * tb_v6082 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6082; }
    { const char * tb_v6083 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6083; }
    { const char * tb_v6084 = "    tb_gpu_add(x0, y0, x1, y1, 0, 0, cc, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6084; }
    { const char * tb_v6085 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6085; }
    { const char * tb_v6086 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6086; }
    { const char * tb_v6087 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6087; }
    { const char * tb_v6088 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6088; }
    { const char * tb_v6089 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v6089; }
    { const char * tb_v6090 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6090; }
    { const char * tb_v6091 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v6091; }
    { const char * tb_v6092 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6092; }
    { const char * tb_v6093 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6093; }
    { const char * tb_v6094 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v6094; }
    { const char * tb_v6095 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v6095; }
    { const char * tb_v6096 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6096; }
    { const char * tb_v6097 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v6097; }
    { const char * tb_v6098 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v6098; }
    { const char * tb_v6099 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6099; }
    { const char * tb_v6100 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6100; }
    { const char * tb_v6101 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6101; }
    { const char * tb_v6102 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6102; }
    { const char * tb_v6103 = "TB_API void tb_gpu_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6103; }
    { const char * tb_v6104 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v6104; }
    { const char * tb_v6105 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6105; }
    { const char * tb_v6106 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v6106; }
    { const char * tb_v6107 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6107; }
    { const char * tb_v6108 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v6108; }
    { const char * tb_v6109 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6109; }
    { const char * tb_v6110 = "// картинка с настоящей прозрачностью (буквы шрифта): видеокарта смешивает с тем, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v6110; }
    { const char * tb_v6111 = "TB_API void tb_gpu_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6111; }
    { const char * tb_v6112 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v6112; }
    { const char * tb_v6113 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6113; }
    { const char * tb_v6114 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v6114; }
    { const char * tb_v6115 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6115; }
    { const char * tb_v6116 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (1u << 29) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v6116; }
    { const char * tb_v6117 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6117; }
    { const char * tb_v6118 = "// треугольник: m = 1 (вид 0, но не прямоугольник); в q и o — три угла, уже по кругу «как надо» (tb_tri_prep).\n"; *(const char * *)tb_grow(v_lines) = tb_v6118; }
    { const char * tb_v6119 = "// Квадрат вокруг строит шейдер, а какие точки внутри — решает то же правило, что на процессоре (tb_tri_in)\n"; *(const char * *)tb_grow(v_lines) = tb_v6119; }
    { const char * tb_v6120 = "TB_API void tb_gpu_triangle(const long long *t, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6120; }
