    { const char * tb_v8306 = "TB_API int tb_vk_buffer(VkDeviceSize size, VkFlags usage, VkBuffer *buf, void **map) { VkDeviceMemory m; return tb_vk_buffer_m(size, usage, buf, map, &m); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8306; }
    { const char * tb_v8307 = "TB_API int tb_vk_buffer_m(VkDeviceSize size, VkFlags usage, VkBuffer *buf, void **map, VkDeviceMemory *memo) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8307; }
    { const char * tb_v8308 = "    VkBufferCreateInfo bi = { 12, 0, 0, size, usage, 0, 0, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8308; }
    { const char * tb_v8309 = "    if (tbvk_CreateBuffer(tb_vk.dev, &bi, 0, buf)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8309; }
    { const char * tb_v8310 = "    VkMemoryRequirements mr; tbvk_GetBufferMemoryRequirements(tb_vk.dev, *buf, &mr);\n"; *(const char * *)tb_grow(v_lines) = tb_v8310; }
    { const char * tb_v8311 = "    int t = tb_vk_memtype(mr.memoryTypeBits, 2 | 4);   // HOST_VISIBLE | HOST_COHERENT\n"; *(const char * *)tb_grow(v_lines) = tb_v8311; }
    { const char * tb_v8312 = "    if (t < 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8312; }
    { const char * tb_v8313 = "    VkMemoryAllocateInfo ai = { 5, 0, mr.size, (uint32_t)t };\n"; *(const char * *)tb_grow(v_lines) = tb_v8313; }
