    { const char * tb_v8315 = "    if (tbvk_AllocateMemory(tb_vk.dev, &ai, 0, &mem) || tbvk_BindBufferMemory(tb_vk.dev, *buf, mem, 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8315; }
    { const char * tb_v8316 = "    *memo = mem;\n"; *(const char * *)tb_grow(v_lines) = tb_v8316; }
