    { const char * tb_v8975 = "TB_API void tb_gfx_key(unsigned char sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8975; }
    { const char * tb_v8976 = "    if (sc == 0xE0) { tb_kext = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8976; }
