    { const char * tb_v8987 = "// --- мышь PS/2: пакеты по 3 байта (по 4 — с колёсиком) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v8987; }
    { const char * tb_v8988 = "TB_API unsigned char tb_mpk[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v8988; }
