    { const char * tb_v8990 = "TB_API void tb_ps2_wait_in(void) { for (int i = 0; i < 100000 && (tb_inb(0x64) & 2); i++) {} }\n"; *(const char * *)tb_grow(v_lines) = tb_v8990; }
    { const char * tb_v8991 = "TB_API int tb_ps2_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8991; }
    { const char * tb_v8992 = "    for (int i = 0; i < 100000; i++) if (tb_inb(0x64) & 1) return tb_inb(0x60);\n"; *(const char * *)tb_grow(v_lines) = tb_v8992; }
