    { const char * tb_v9016 = "    if (r[0] != 0x3442554Au) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9016; }
    { const char * tb_v9017 = "    tb_vmm_call(41, 0x53424152u, r);                     // точные координаты\n"; *(const char * *)tb_grow(v_lines) = tb_v9017; }
    { const char * tb_v9018 = "    tb_vmm = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9018; }
    { const char * tb_v9019 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9019; }
    { const char * tb_v9020 = "TB_API void tb_vmm_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9020; }
    { const char * tb_v9021 = "    uint32_t r[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v9021; }
    { const char * tb_v9022 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9022; }
    { const char * tb_v9023 = "        tb_vmm_call(40, 0, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v9023; }
