    { const char * tb_v9026 = "        tb_vmm_call(39, 4, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v9026; }
    { const char * tb_v9027 = "        tb_mx = (int)((uint64_t)r[1] * (uint64_t)tb_gw / 65536);\n"; *(const char * *)tb_grow(v_lines) = tb_v9027; }
