    { const char * tb_v9035 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9035; }
    { const char * tb_v9036 = "TB_API void tb_mouse_irq(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9036; }
    { const char * tb_v9037 = "    unsigned char st = tb_inb(0x64);\n"; *(const char * *)tb_grow(v_lines) = tb_v9037; }
    { const char * tb_v9038 = "    if (!(st & 1)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9038; }
