    { const char * tb_v9041 = "    if (tb_vmm) { tb_vmm_read(); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9041; }
    { const char * tb_v9042 = "    if (tb_mpn == 0 && !(b & 8)) return;           // первый байт пакета всегда с битом 3\n"; *(const char * *)tb_grow(v_lines) = tb_v9042; }
    { const char * tb_v9043 = "    tb_mpk[tb_mpn++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v9043; }
