    { const char * tb_v9047 = "    if (tb_mpk[0] & 0xC0) dx = dy = 0;            // переполнение: пакет не верен\n"; *(const char * *)tb_grow(v_lines) = tb_v9047; }
    { const char * tb_v9048 = "    tb_mx += dx; tb_my -= dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v9048; }
    { const char * tb_v9049 = "    if (tb_mx < 0) tb_mx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9049; }
    { const char * tb_v9050 = "    if (tb_my < 0) tb_my = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9050; }
    { const char * tb_v9051 = "    if (tb_mx >= tb_gw) tb_mx = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9051; }
