    { const char * tb_v9053 = "    int down = tb_mpk[0] & 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9053; }
    { const char * tb_v9054 = "    if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9054; }
    { const char * tb_v9055 = "    tb_mdown = down;\n"; *(const char * *)tb_grow(v_lines) = tb_v9055; }
