    { const char * tb_v10544 = "    while (XPending(tb_dpy)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10544; }
    { const char * tb_v10545 = "        XEvent e; XNextEvent(tb_dpy, &e);\n"; *(const char * *)tb_grow(v_lines) = tb_v10545; }
    { const char * tb_v10546 = "        if (tb_wn > 1) { int w = tb_wfind((uintptr_t)e.xany.window); if (w >= 0) tb_wswitch(w); }   // событие другого окна\n"; *(const char * *)tb_grow(v_lines) = tb_v10546; }
    { const char * tb_v10547 = "        if (e.type == SelectionRequest) tb_x_clip_answer(&e.xselectionrequest);\n"; *(const char * *)tb_grow(v_lines) = tb_v10547; }
    { const char * tb_v10548 = "        else if (e.type == FocusOut) memset(tb_keys, 0, sizeof tb_keys);\n"; *(const char * *)tb_grow(v_lines) = tb_v10548; }
    { const char * tb_v10549 = "        else if (e.type == ClientMessage && (Atom)e.xclient.data.l[0] == tb_wm_del) tb_gclosed = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10549; }
    { const char * tb_v10550 = "        else if (e.type == KeyPress || e.type == KeyRelease) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10550; }
    { const char * tb_v10551 = "            int k = tb_x_key(XLookupKeysym(&e.xkey, 0));\n"; *(const char * *)tb_grow(v_lines) = tb_v10551; }
    { const char * tb_v10552 = "            if (k) { tb_keys[k] = e.type == KeyPress; if (tb_keys[k]) tb_ktap[k] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10552; }
    { const char * tb_v10553 = "            if (e.type == KeyPress) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10553; }
    { const char * tb_v10554 = "                char buf[16]; KeySym ks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10554; }
    { const char * tb_v10555 = "                XLookupString(&e.xkey, buf, sizeof buf, &ks, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v10555; }
    { const char * tb_v10556 = "                if (!(e.xkey.state & ControlMask)) tb_type_cp(tb_x_uni(ks));\n"; *(const char * *)tb_grow(v_lines) = tb_v10556; }
    { const char * tb_v10557 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v10557; }
    { const char * tb_v10558 = "        } else if (e.type == ButtonPress || e.type == ButtonRelease) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10558; }
    { const char * tb_v10559 = "            if (e.xbutton.button == 1) { tb_mdown = e.type == ButtonPress; if (tb_mdown) tb_mtap = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10559; }
    { const char * tb_v10560 = "            if (e.xbutton.button == 8 || e.xbutton.button == 9) tb_side(e.xbutton.button - 8, e.type == ButtonPress);\n"; *(const char * *)tb_grow(v_lines) = tb_v10560; }
    { const char * tb_v10561 = "            if (e.type == ButtonPress && e.xbutton.button == 4) tb_wheel_add(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10561; }
    { const char * tb_v10562 = "            if (e.type == ButtonPress && e.xbutton.button == 5) tb_wheel_add(-1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10562; }
    { const char * tb_v10563 = "            tb_mx = e.xbutton.x; tb_my = e.xbutton.y;\n"; *(const char * *)tb_grow(v_lines) = tb_v10563; }
    { const char * tb_v10564 = "        } else if (e.type == MotionNotify) tb_mouse_at(e.xmotion.x, e.xmotion.y);\n"; *(const char * *)tb_grow(v_lines) = tb_v10564; }
    { const char * tb_v10565 = "        else if (e.type == ConfigureNotify && (e.xconfigure.width != tb_gw || e.xconfigure.height != tb_gh)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10565; }
    { const char * tb_v10566 = "            tb_new_w = e.xconfigure.width; tb_new_h = e.xconfigure.height;\n"; *(const char * *)tb_grow(v_lines) = tb_v10566; }
    { const char * tb_v10567 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10567; }
    { const char * tb_v10568 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10568; }
    { const char * tb_v10569 = "    if (tb_wcur != was) tb_wswitch(was);\n"; *(const char * *)tb_grow(v_lines) = tb_v10569; }
    { const char * tb_v10570 = "    if (tb_mlock && tb_mwarp) { XWarpPointer(tb_dpy, None, tb_xw, 0, 0, 0, 0, tb_gw / 2, tb_gh / 2); tb_mwarp = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10570; }
    { const char * tb_v10571 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v10571; }
    { const char * tb_v10572 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10572; }
    { const char * tb_v10573 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v10573; }
    { const char * tb_v10574 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v10574; }
    { const char * tb_v10575 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v10575; }
    { const char * tb_v10576 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v10576; }
    { const char * tb_v10577 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v10577; }
    { const char * tb_v10578 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v10578; }
    { const char * tb_v10579 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10579; }
    { const char * tb_v10580 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10580; }
    { const char * tb_v10581 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v10581; }
    { const char * tb_v10582 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10582; }
    { const char * tb_v10583 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10583; }
    { const char * tb_v10584 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v10584; }
    { const char * tb_v10585 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10585; }
    { const char * tb_v10586 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v10586; }
    { const char * tb_v10587 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v10587; }
    { const char * tb_v10588 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v10588; }
    { const char * tb_v10589 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10589; }
    { const char * tb_v10590 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v10590; }
    { const char * tb_v10591 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v10591; }
    { const char * tb_v10592 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v10592; }
    { const char * tb_v10593 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v10593; }
    { const char * tb_v10594 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10594; }
    { const char * tb_v10595 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10595; }
    { const char * tb_v10596 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10596; }
    { const char * tb_v10597 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10597; }
    { const char * tb_v10598 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10598; }
    { const char * tb_v10599 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v10599; }
    { const char * tb_v10600 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v10600; }
    { const char * tb_v10601 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v10601; }
    { const char * tb_v10602 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v10602; }
    { const char * tb_v10603 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10603; }
    { const char * tb_v10604 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10604; }
    { const char * tb_v10605 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v10605; }
    { const char * tb_v10606 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v10606; }
    { const char * tb_v10607 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10607; }
    { const char * tb_v10608 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10608; }
    { const char * tb_v10609 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v10609; }
    { const char * tb_v10610 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10610; }
    { const char * tb_v10611 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v10611; }
    { const char * tb_v10612 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10612; }
    { const char * tb_v10613 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10613; }
    { const char * tb_v10614 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10614; }
    { const char * tb_v10615 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10615; }
    { const char * tb_v10616 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v10616; }
    { const char * tb_v10617 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10617; }
    { const char * tb_v10618 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v10618; }
    { const char * tb_v10619 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v10619; }
    { const char * tb_v10620 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10620; }
    { const char * tb_v10621 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10621; }
    { const char * tb_v10622 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v10622; }
    { const char * tb_v10623 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v10623; }
    { const char * tb_v10624 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v10624; }
    { const char * tb_v10625 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10625; }
    { const char * tb_v10626 = "        fprintf(stderr, \"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\", diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v10626; }
    { const char * tb_v10627 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10627; }
    { const char * tb_v10628 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10628; }
    { const char * tb_v10629 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v10629; }
    { const char * tb_v10630 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v10630; }
    { const char * tb_v10631 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v10631; }
    { const char * tb_v10632 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10632; }
    { const char * tb_v10633 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10633; }
    { const char * tb_v10634 = "// ---- несколько окон (1.3): window_new, window_use, window_close, window_shown ----\n"; *(const char * *)tb_grow(v_lines) = tb_v10634; }
    { const char * tb_v10635 = "// Главное окно (window_open) — номер 0. У каждого окна свои точки, размер, мышь, клавиши и глубина 3D.\n"; *(const char * *)tb_grow(v_lines) = tb_v10635; }
    { const char * tb_v10636 = "// Текущее окно лежит в обычных переменных (tb_px, tb_gw, tb_keys ...), остальные ждут в tb_wins.\n"; *(const char * *)tb_grow(v_lines) = tb_v10636; }
    { const char * tb_v10637 = "// Новые окна рисует процессор; видеокарта — у главного окна\n"; *(const char * *)tb_grow(v_lines) = tb_v10637; }
    { const char * tb_v10638 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v10638; }
    { const char * tb_v10639 = "    int used;\n"; *(const char * *)tb_grow(v_lines) = tb_v10639; }
    { const char * tb_v10640 = "    uint32_t *px; int gw, gh, gclosed, mx, my, mdown, mtap, wheel; double wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v10640; }
    { const char * tb_v10641 = "    int mside[2], mside_tap[2], ntyped; char typed[512];\n"; *(const char * *)tb_grow(v_lines) = tb_v10641; }
    { const char * tb_v10642 = "    unsigned char keys[256], ktap[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v10642; }
    { const char * tb_v10643 = "    int new_w, new_h, resizable, gpu_on, zclr, gzclr; uint32_t *zb; long long zb_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10643; }
    { const char * tb_v10644 = "    TB_WPLAT\n"; *(const char * *)tb_grow(v_lines) = tb_v10644; }
    { const char * tb_v10645 = "} tb_wslot;\n"; *(const char * *)tb_grow(v_lines) = tb_v10645; }
    { const char * tb_v10646 = "static tb_wslot tb_wins[TB_WMAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v10646; }
    { const char * tb_v10647 = "#define TB_WFIELDS(X) X(px, tb_px) X(gw, tb_gw) X(gh, tb_gh) X(gclosed, tb_gclosed) X(mx, tb_mx) X(my, tb_my) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v10647; }
    { const char * tb_v10648 = "    X(mdown, tb_mdown) X(mtap, tb_mtap) X(wheel, tb_wheel) X(wheel_f, tb_wheel_f) X(ntyped, tb_ntyped) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v10648; }
    { const char * tb_v10649 = "    X(new_w, tb_new_w) X(new_h, tb_new_h) X(resizable, tb_resizable) X(gpu_on, tb_gpu_on) X(zclr, tb_zclr) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v10649; }
    { const char * tb_v10650 = "    X(gzclr, tb_gzclr) X(zb, tb_zb) X(zb_n, tb_zb_n)\n"; *(const char * *)tb_grow(v_lines) = tb_v10650; }
    { const char * tb_v10651 = "#define TB_WSAVE1(f, g) s->f = g;\n"; *(const char * *)tb_grow(v_lines) = tb_v10651; }
    { const char * tb_v10652 = "#define TB_WLOAD1(f, g) g = s->f;\n"; *(const char * *)tb_grow(v_lines) = tb_v10652; }
    { const char * tb_v10653 = "static void tb_wsave(tb_wslot *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10653; }
    { const char * tb_v10654 = "    TB_WFIELDS(TB_WSAVE1)\n"; *(const char * *)tb_grow(v_lines) = tb_v10654; }
    { const char * tb_v10655 = "    memcpy(s->mside, tb_mside, sizeof s->mside); memcpy(s->mside_tap, tb_mside_tap, sizeof s->mside_tap);\n"; *(const char * *)tb_grow(v_lines) = tb_v10655; }
    { const char * tb_v10656 = "    memcpy(s->typed, tb_typed, sizeof s->typed); memcpy(s->keys, tb_keys, sizeof s->keys); memcpy(s->ktap, tb_ktap, sizeof s->ktap);\n"; *(const char * *)tb_grow(v_lines) = tb_v10656; }
    { const char * tb_v10657 = "    TB_WPLAT_SAVE(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v10657; }
    { const char * tb_v10658 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10658; }
    { const char * tb_v10659 = "static void tb_wload(tb_wslot *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10659; }
    { const char * tb_v10660 = "    TB_WFIELDS(TB_WLOAD1)\n"; *(const char * *)tb_grow(v_lines) = tb_v10660; }
    { const char * tb_v10661 = "    memcpy(tb_mside, s->mside, sizeof s->mside); memcpy(tb_mside_tap, s->mside_tap, sizeof s->mside_tap);\n"; *(const char * *)tb_grow(v_lines) = tb_v10661; }
    { const char * tb_v10662 = "    memcpy(tb_typed, s->typed, sizeof s->typed); memcpy(tb_keys, s->keys, sizeof s->keys); memcpy(tb_ktap, s->ktap, sizeof s->ktap);\n"; *(const char * *)tb_grow(v_lines) = tb_v10662; }
    { const char * tb_v10663 = "    TB_WPLAT_LOAD(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v10663; }
    { const char * tb_v10664 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10664; }
    { const char * tb_v10665 = "TB_API int tb_wfind(uintptr_t h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10665; }
    { const char * tb_v10666 = "    for (int i = 0; i < tb_wn; i++) if (tb_wins[i].used && tb_whand[i] == h && h) return i;\n"; *(const char * *)tb_grow(v_lines) = tb_v10666; }
    { const char * tb_v10667 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10667; }
    { const char * tb_v10668 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10668; }
    { const char * tb_v10669 = "// сделать окно i текущим: 3D, которое ждало, дорисовывается в прежнее окно\n"; *(const char * *)tb_grow(v_lines) = tb_v10669; }
    { const char * tb_v10670 = "TB_API void tb_wswitch(int i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10670; }
    { const char * tb_v10671 = "    if (i == tb_wcur || i < 0 || i >= tb_wn || !tb_wins[i].used) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10671; }
    { const char * tb_v10672 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v10672; }
    { const char * tb_v10673 = "    tb_wsave(&tb_wins[tb_wcur]);\n"; *(const char * *)tb_grow(v_lines) = tb_v10673; }
