    { const char * tb_v10830 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10830; }
    { const char * tb_v10831 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v10831; }
    { const char * tb_v10832 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10832; }
    { const char * tb_v10833 = "    if (tb_wn > 1) tb_windows_show();\n"; *(const char * *)tb_grow(v_lines) = tb_v10833; }
