    { const char * tb_v10835 = "    TB_SCENE();        // сцена 3D, которая ждала (тени, прозрачные) — в этот кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v10835; }
    { const char * tb_v10836 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v10836; }
    { const char * tb_v10837 = "    if (tb_wn > 1) tb_windows_after();\n"; *(const char * *)tb_grow(v_lines) = tb_v10837; }
