    { const char * tb_v10839 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v10839; }
    { const char * tb_v10840 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v10840; }
    { const char * tb_v10841 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10841; }
