    { const char * tb_v10876 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10876; }
    { const char * tb_v10877 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v10877; }
    { const char * tb_v10878 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10878; }
    { const char * tb_v10879 = "    uint32_t t = (c >> 24) & 255, a = 255 - t;\n"; *(const char * *)tb_grow(v_lines) = tb_v10879; }
