    { const char * tb_v10881 = "    uint32_t g = ((c & 0x00FF00) * a + (d & 0x00FF00) * t + 0x008000) >> 8 & 0x00FF00;\n"; *(const char * *)tb_grow(v_lines) = tb_v10881; }
    { const char * tb_v10882 = "    return rb | g;\n"; *(const char * *)tb_grow(v_lines) = tb_v10882; }
