    { const char * tb_v10885 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v10885; }
    { const char * tb_v10886 = "    if ((c >> 24) & 255) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10886; }
    { const char * tb_v10887 = "        for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c);\n"; *(const char * *)tb_grow(v_lines) = tb_v10887; }
    { const char * tb_v10888 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10888; }
    { const char * tb_v10889 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10889; }
    { const char * tb_v10890 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v10890; }
    { const char * tb_v10891 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10891; }
    { const char * tb_v10892 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10892; }
    { const char * tb_v10893 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v10893; }
    { const char * tb_v10894 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10894; }
