    { const char * tb_v10906 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10906; }
    { const char * tb_v10907 = "// draw_shadow(x, y, w, h, r, size, c): мягкая тень скруглённого прямоугольника — внутри цвет c,\n"; *(const char * *)tb_grow(v_lines) = tb_v10907; }
    { const char * tb_v10908 = "// снаружи к size точкам сходит на нет. Корень считается только у кольца и углов, середина — простое смешивание.\n"; *(const char * *)tb_grow(v_lines) = tb_v10908; }
    { const char * tb_v10909 = "TB_API void tb_draw_shadow(long long x, long long y, long long w, long long h, long long r, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10909; }
    { const char * tb_v10910 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v10910; }
    { const char * tb_v10911 = "    if (!tb_px || w <= 0 || h <= 0 || size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10911; }
    { const char * tb_v10912 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v10912; }
    { const char * tb_v10913 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v10913; }
    { const char * tb_v10914 = "    if (tb_gpu_on) {                                   // видеокарта: слоями (без сглаживания)\n"; *(const char * *)tb_grow(v_lines) = tb_v10914; }
    { const char * tb_v10915 = "        for (long long k = size; k > 0; k -= 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10915; }
    { const char * tb_v10916 = "            double f = 1.0 - (double)k / size;\n"; *(const char * *)tb_grow(v_lines) = tb_v10916; }
    { const char * tb_v10917 = "            long long a = (long long)((255 - ((c >> 24) & 255)) * f * f / (size / 2.0) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v10917; }
    { const char * tb_v10918 = "            if (a > 0) tb_gpu_rect(x - k, y - k + r, w + 2 * k, h + 2 * k - 2 * r, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v10918; }
    { const char * tb_v10919 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10919; }
    { const char * tb_v10920 = "        if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10920; }
    { const char * tb_v10921 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10921; }
    { const char * tb_v10922 = "    double hw = w / 2.0, hh = h / 2.0, cx = x + hw, cy = y + hh;\n"; *(const char * *)tb_grow(v_lines) = tb_v10922; }
    { const char * tb_v10923 = "    long long y0 = y - size < 0 ? 0 : y - size, y1 = y + h + size > tb_gh ? tb_gh : y + h + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v10923; }
    { const char * tb_v10924 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10924; }
    { const char * tb_v10925 = "        double py = j + 0.5, dy = fabs(py - cy) - (hh - r);\n"; *(const char * *)tb_grow(v_lines) = tb_v10925; }
    { const char * tb_v10926 = "        if (dy < 0) dy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10926; }
    { const char * tb_v10927 = "        long long xa = x - size < 0 ? 0 : x - size, xb = x + w + size > tb_gw ? tb_gw : x + w + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v10927; }
    { const char * tb_v10928 = "        for (long long i = xa; i < xb; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10928; }
    { const char * tb_v10929 = "            double px = i + 0.5, dx = fabs(px - cx) - (hw - r);\n"; *(const char * *)tb_grow(v_lines) = tb_v10929; }
    { const char * tb_v10930 = "            if (dx < 0) dx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10930; }
    { const char * tb_v10931 = "            if (dx == 0 && dy == 0) { tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10931; }
    { const char * tb_v10932 = "            double d = sqrt(dx * dx + dy * dy) - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v10932; }
    { const char * tb_v10933 = "            if (d >= size) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v10933; }
    { const char * tb_v10934 = "            double f = d <= 0 ? 1 : 1 - d / size;\n"; *(const char * *)tb_grow(v_lines) = tb_v10934; }
    { const char * tb_v10935 = "            tb_cover(i, j, (uint32_t)c, f * f);\n"; *(const char * *)tb_grow(v_lines) = tb_v10935; }
