    { const char * tb_v10939 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v10939; }
    { const char * tb_v10940 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10940; }
    { const char * tb_v10941 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v10941; }
    { const char * tb_v10942 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10942; }
    { const char * tb_v10943 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v10943; }
    { const char * tb_v10944 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v10944; }
    { const char * tb_v10945 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10945; }
    { const char * tb_v10946 = "        while (*s == ' ' || *s == ',') s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v10946; }
    { const char * tb_v10947 = "        const char *e = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v10947; }
    { const char * tb_v10948 = "        while (*e && *e != ' ' && *e != ',') e++;\n"; *(const char * *)tb_grow(v_lines) = tb_v10948; }
    { const char * tb_v10949 = "        for (int i = 0; i < 9; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v10949; }
    { const char * tb_v10950 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v10950; }
    { const char * tb_v10951 = "        s = e;\n"; *(const char * *)tb_grow(v_lines) = tb_v10951; }
    { const char * tb_v10952 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10952; }
