    { const char * tb_v10981 = "        else for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = cc & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v10981; }
    { const char * tb_v10982 = "        // углы: покрытие точки по расстоянию до центра угла\n"; *(const char * *)tb_grow(v_lines) = tb_v10982; }
