    { const char * tb_v11011 = "        sb += (long long)(in & 255) - (out & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v11011; }
    { const char * tb_v11012 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11012; }
    { const char * tb_v11013 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11013; }
    { const char * tb_v11014 = "// матовое стекло: размытие прямоугольника кадра. Большое размытие (r >= 4) считается на картинке\n"; *(const char * *)tb_grow(v_lines) = tb_v11014; }
    { const char * tb_v11015 = "// вдвое меньше (в 4 раза меньше точек), потом плавно растягивается обратно — на глаз то же самое.\n"; *(const char * *)tb_grow(v_lines) = tb_v11015; }
    { const char * tb_v11016 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11016; }
    { const char * tb_v11017 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v11017; }
