    { const char * tb_v11036 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v11036; }
    { const char * tb_v11037 = "        for (long long yy = 0; yy < bh; yy++) memcpy(b + yy * bw, tb_px + (y0 + yy) * tb_gw + x0, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v11037; }
    { const char * tb_v11038 = "    for (int pass = 0; pass < 3; pass++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11038; }
    { const char * tb_v11039 = "        for (long long yy = 0; yy < bh; yy++) tb_blur_run(b + yy * bw, bw, 1, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v11039; }
    { const char * tb_v11040 = "        for (long long xx = 0; xx < bw; xx++) tb_blur_run(b + xx, bh, bw, br, tmp);\n"; *(const char * *)tb_grow(v_lines) = tb_v11040; }
    { const char * tb_v11041 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11041; }
    { const char * tb_v11042 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v11042; }
    { const char * tb_v11043 = "        // обратно: каждая точка — смесь четырёх соседних из маленькой картинки\n"; *(const char * *)tb_grow(v_lines) = tb_v11043; }
    { const char * tb_v11044 = "        for (long long yy = 0; yy < H; yy++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11044; }
    { const char * tb_v11045 = "            long long fy = yy * 128 - 64; if (fy < 0) fy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11045; }
    { const char * tb_v11046 = "            long long iy = fy >> 8, ty = fy & 255, iy2 = iy + 1 < bh ? iy + 1 : iy;\n"; *(const char * *)tb_grow(v_lines) = tb_v11046; }
    { const char * tb_v11047 = "            for (long long xx = 0; xx < W; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11047; }
