    { const char * tb_v11049 = "                long long ix = fx >> 8, tx = fx & 255, ix2 = ix + 1 < bw ? ix + 1 : ix;\n"; *(const char * *)tb_grow(v_lines) = tb_v11049; }
    { const char * tb_v11050 = "                uint32_t p = b[iy * bw + ix], q = b[iy * bw + ix2], u = b[iy2 * bw + ix], v = b[iy2 * bw + ix2], o = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11050; }
