    { const char * tb_v11062 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11062; }
    { const char * tb_v11063 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v11063; }
