    { const char * tb_v11085 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v11085; }
    { const char * tb_v11086 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v11086; }
    { const char * tb_v11087 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11087; }
    { const char * tb_v11088 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11088; }
    { const char * tb_v11089 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11089; }
    { const char * tb_v11090 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11090; }
    { const char * tb_v11091 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v11091; }
    { const char * tb_v11092 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11092; }
    { const char * tb_v11093 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v11093; }
    { const char * tb_v11094 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v11094; }
    { const char * tb_v11095 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v11095; }
    { const char * tb_v11096 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v11096; }
    { const char * tb_v11097 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v11097; }
    { const char * tb_v11098 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11098; }
    { const char * tb_v11099 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v11099; }
    { const char * tb_v11100 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11100; }
    { const char * tb_v11101 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v11101; }
    { const char * tb_v11102 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v11102; }
    { const char * tb_v11103 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11103; }
    { const char * tb_v11104 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11104; }
    { const char * tb_v11105 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v11105; }
    { const char * tb_v11106 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11106; }
    { const char * tb_v11107 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v11107; }
    { const char * tb_v11108 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v11108; }
    { const char * tb_v11109 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v11109; }
    { const char * tb_v11110 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v11110; }
    { const char * tb_v11111 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11111; }
    { const char * tb_v11112 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v11112; }
    { const char * tb_v11113 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11113; }
    { const char * tb_v11114 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11114; }
    { const char * tb_v11115 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v11115; }
    { const char * tb_v11116 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v11116; }
    { const char * tb_v11117 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11117; }
    { const char * tb_v11118 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v11118; }
    { const char * tb_v11119 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v11119; }
    { const char * tb_v11120 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11120; }
    { const char * tb_v11121 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v11121; }
    { const char * tb_v11122 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v11122; }
    { const char * tb_v11123 = "    return d < 0 ? 0u : d > 16777215 ? 16777215u : (uint32_t)d;\n"; *(const char * *)tb_grow(v_lines) = tb_v11123; }
    { const char * tb_v11124 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11124; }
    { const char * tb_v11125 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v11125; }
    { const char * tb_v11126 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v11126; }
    { const char * tb_v11127 = "// треугольник с картинкой: tb_tex_cur — его запись текстуры (иначе 0). Точка картинки для (x, y):\n"; *(const char * *)tb_grow(v_lines) = tb_v11127; }
    { const char * tb_v11128 = "// W = (2^24 - глубина) >> 4 (это 1/z), u = (плоскость u·W) / W — с перспективой, как на видеокарте (tbt.frag)\n"; *(const char * *)tb_grow(v_lines) = tb_v11128; }
    { const char * tb_v11129 = "TB_API const tb_gtex_t *tb_tex_cur = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11129; }
    { const char * tb_v11130 = "TB_INL long long tb_fdiv(long long a, long long b);\n"; *(const char * *)tb_grow(v_lines) = tb_v11130; }
    { const char * tb_v11131 = "TB_INL int tb_tex_px(const tb_gtex_t *tx, uint32_t d, long long x, long long y, uint32_t *out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11131; }
    { const char * tb_v11132 = "    long long W = (16777216 - (long long)d) >> 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v11132; }
    { const char * tb_v11133 = "    if (W < 1) W = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11133; }
    { const char * tb_v11134 = "    long long su = (tx->cu + tx->au * (2 * x + 1) + tx->bu * (2 * y + 1)) >> 6, sv = (tx->cv + tx->av * (2 * x + 1) + tx->bv * (2 * y + 1)) >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v11134; }
    { const char * tb_v11135 = "    long long u = tb_fdiv(tb_fdiv(su, W), 16), v = tb_fdiv(tb_fdiv(sv, W), 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v11135; }
    { const char * tb_v11136 = "    u -= tb_fdiv(u, tx->w) * (long long)tx->w;   // повтор картинки: 0…w-1\n"; *(const char * *)tb_grow(v_lines) = tb_v11136; }
    { const char * tb_v11137 = "    v -= tb_fdiv(v, tx->h) * (long long)tx->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v11137; }
    { const char * tb_v11138 = "    *out = tb_imgpx[tx->off + (uint32_t)v * tx->w + (uint32_t)u];\n"; *(const char * *)tb_grow(v_lines) = tb_v11138; }
    { const char * tb_v11139 = "    return (*out >> 24) >= 128;\n"; *(const char * *)tb_grow(v_lines) = tb_v11139; }
    { const char * tb_v11140 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11140; }
    { const char * tb_v11141 = "// точка картинки × оттенок (свет): (т · о + 127) / 255 по каждому цвету\n"; *(const char * *)tb_grow(v_lines) = tb_v11141; }
    { const char * tb_v11142 = "TB_INL uint32_t tb_tex_tint(uint32_t t, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11142; }
    { const char * tb_v11143 = "    uint32_t r = (((t >> 16) & 255) * ((c >> 16) & 255) + 127) / 255, g = (((t >> 8) & 255) * ((c >> 8) & 255) + 127) / 255,\n"; *(const char * *)tb_grow(v_lines) = tb_v11143; }
    { const char * tb_v11144 = "             b = ((t & 255) * (c & 255) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v11144; }
    { const char * tb_v11145 = "    return (c & 0xFF000000u) | (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v11145; }
    { const char * tb_v11146 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11146; }
    { const char * tb_v11147 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11147; }
    { const char * tb_v11148 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11148; }
    { const char * tb_v11149 = "    const tb_gtex_t *tx = pl ? tb_tex_cur : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11149; }
    { const char * tb_v11150 = "    if (gpu) { if (tx) tb_gpu_tri3t(t, c, pl, tx); else if (pl) tb_gpu_tri3(t, c, pl); else tb_gpu_triangle(t, c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v11150; }
    { const char * tb_v11151 = "    if (cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11151; }
    { const char * tb_v11152 = "        long long xa = t[0], xb = t[0], ya = t[1], yb = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v11152; }
    { const char * tb_v11153 = "        for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11153; }
    { const char * tb_v11154 = "            if (t[i] < xa) xa = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v11154; }
    { const char * tb_v11155 = "            if (t[i] > xb) xb = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v11155; }
    { const char * tb_v11156 = "            if (t[i + 1] < ya) ya = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v11156; }
    { const char * tb_v11157 = "            if (t[i + 1] > yb) yb = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v11157; }
    { const char * tb_v11158 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v11158; }
    { const char * tb_v11159 = "        if (xa < 0) xa = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11159; }
    { const char * tb_v11160 = "        if (ya < 0) ya = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11160; }
    { const char * tb_v11161 = "        if (xb > tb_gw - 1) xb = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11161; }
    { const char * tb_v11162 = "        if (yb > tb_gh - 1) yb = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11162; }
    { const char * tb_v11163 = "        for (long long y = ya; y <= yb; y++)\n"; *(const char * *)tb_grow(v_lines) = tb_v11163; }
    { const char * tb_v11164 = "            for (long long x = xa; x <= xb; x++)\n"; *(const char * *)tb_grow(v_lines) = tb_v11164; }
    { const char * tb_v11165 = "                if (tb_tri_edge(t[0], t[1], t[2], t[3], x, y) && tb_tri_edge(t[2], t[3], t[4], t[5], x, y) &&\n"; *(const char * *)tb_grow(v_lines) = tb_v11165; }
    { const char * tb_v11166 = "                    tb_tri_edge(t[4], t[5], t[0], t[1], x, y)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11166; }
    { const char * tb_v11167 = "                    uint32_t col = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v11167; }
    { const char * tb_v11168 = "                    if (pl) {   // 3D: точка видна, если ближе того, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v11168; }
    { const char * tb_v11169 = "                        uint32_t d = tb_tri3_depth(pl, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v11169; }
    { const char * tb_v11170 = "                        if (d >= tb_zb[y * tb_gw + x]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v11170; }
    { const char * tb_v11171 = "                        if (tx) {   // картинка: прозрачная точка (меньше 128) — дырка, глубину не пишет\n"; *(const char * *)tb_grow(v_lines) = tb_v11171; }
    { const char * tb_v11172 = "                            uint32_t tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v11172; }
    { const char * tb_v11173 = "                            if (!tb_tex_px(tx, d, x, y, &tp)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v11173; }
    { const char * tb_v11174 = "                            col = tb_tex_tint(tp, col);\n"; *(const char * *)tb_grow(v_lines) = tb_v11174; }
    { const char * tb_v11175 = "                        }\n"; *(const char * *)tb_grow(v_lines) = tb_v11175; }
    { const char * tb_v11176 = "                        tb_zb[y * tb_gw + x] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v11176; }
    { const char * tb_v11177 = "                    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11177; }
    { const char * tb_v11178 = "                    tb_px[y * tb_gw + x] = col;\n"; *(const char * *)tb_grow(v_lines) = tb_v11178; }
    { const char * tb_v11179 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v11179; }
    { const char * tb_v11180 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11180; }
    { const char * tb_v11181 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11181; }
    { const char * tb_v11182 = "static void tb_tri_draw_i(long long *t, long long c, const uint32_t *pl) { tb_tri_draw_x(t, c, pl, tb_gpu_on, TB_CPU_DRAW); }\n"; *(const char * *)tb_grow(v_lines) = tb_v11182; }
    { const char * tb_v11183 = "// многоугольник с углами-дробями (3D после проекции, огромные треугольники): обрезаем рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v11183; }
    { const char * tb_v11184 = "// вокруг окна (±2048 точек, но не дальше ±8192), углы округляем, режем веером из первого угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v11184; }
    { const char * tb_v11185 = "// Общие углы округляются одинаково, поэтому соседние треугольники стыкуются без щелей\n"; *(const char * *)tb_grow(v_lines) = tb_v11185; }
    { const char * tb_v11186 = "// округление до ближайшего целого (половина — вверх); быстрее llround, одно и то же везде\n"; *(const char * *)tb_grow(v_lines) = tb_v11186; }
    { const char * tb_v11187 = "TB_INL long long tb_rnd(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11187; }
    { const char * tb_v11188 = "    long long r = (long long)(x + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v11188; }
    { const char * tb_v11189 = "    if ((double)r > x + 0.5) r--;\n"; *(const char * *)tb_grow(v_lines) = tb_v11189; }
    { const char * tb_v11190 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v11190; }
    { const char * tb_v11191 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11191; }
    { const char * tb_v11192 = "static void tb_poly_draw(double *px, double *py, int n, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11192; }
    { const char * tb_v11193 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11193; }
    { const char * tb_v11194 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v11194; }
    { const char * tb_v11195 = "    if (gy1 > 8192) gy1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v11195; }
    { const char * tb_v11196 = "    double ax[16], ay[16], bx[16], by[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v11196; }
    { const char * tb_v11197 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11197; }
    { const char * tb_v11198 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v11198; }
    { const char * tb_v11199 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11199; }
    { const char * tb_v11200 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11200; }
    { const char * tb_v11201 = "            int j = (i + 1) % n;\n"; *(const char * *)tb_grow(v_lines) = tb_v11201; }
    { const char * tb_v11202 = "            double vi = side == 0 ? ax[i] - gx0 : side == 1 ? gx1 - ax[i] : side == 2 ? ay[i] - gy0 : gy1 - ay[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v11202; }
    { const char * tb_v11203 = "            double vj = side == 0 ? ax[j] - gx0 : side == 1 ? gx1 - ax[j] : side == 2 ? ay[j] - gy0 : gy1 - ay[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v11203; }
    { const char * tb_v11204 = "            if (vi >= 0) { bx[m] = ax[i]; by[m] = ay[i]; m++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11204; }
    { const char * tb_v11205 = "            if ((vi >= 0) != (vj >= 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11205; }
    { const char * tb_v11206 = "                double k = vi / (vi - vj);\n"; *(const char * *)tb_grow(v_lines) = tb_v11206; }
    { const char * tb_v11207 = "                bx[m] = ax[i] + (ax[j] - ax[i]) * k; by[m] = ay[i] + (ay[j] - ay[i]) * k; m++;\n"; *(const char * *)tb_grow(v_lines) = tb_v11207; }
    { const char * tb_v11208 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v11208; }
    { const char * tb_v11209 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v11209; }
    { const char * tb_v11210 = "        n = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v11210; }
    { const char * tb_v11211 = "        for (int i = 0; i < n; i++) { ax[i] = bx[i]; ay[i] = by[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11211; }
    { const char * tb_v11212 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11212; }
