    { const char * tb_v11221 = "TB_API void tb_draw_triangle(long long x1, long long y1, long long x2, long long y2, long long x3, long long y3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11221; }
    { const char * tb_v11222 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v11222; }
