    { const char * tb_v11230 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11230; }
    { const char * tb_v11231 = "// картинка из load_image: левый верхний угол в (x, y); прозрачные точки (меньше 128) не рисуются\n"; *(const char * *)tb_grow(v_lines) = tb_v11231; }
    { const char * tb_v11232 = "TB_API void tb_draw_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11232; }
    { const char * tb_v11233 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v11233; }
    { const char * tb_v11234 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11234; }
    { const char * tb_v11235 = "    if (tb_gpu_on) tb_gpu_image(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v11235; }
    { const char * tb_v11236 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11236; }
    { const char * tb_v11237 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v11237; }
    { const char * tb_v11238 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v11238; }
    { const char * tb_v11239 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v11239; }
    { const char * tb_v11240 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v11240; }
    { const char * tb_v11241 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11241; }
    { const char * tb_v11242 = "            uint32_t v = src[j * im->w + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v11242; }
    { const char * tb_v11243 = "            if ((v >> 24) >= 128) tb_px[(y + j) * tb_gw + x + i] = v & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v11243; }
    { const char * tb_v11244 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v11244; }
    { const char * tb_v11245 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11245; }
    { const char * tb_v11246 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11246; }
    { const char * tb_v11247 = "// то же с настоящей прозрачностью: точка = округл(цвет * a / 255) + округл(фон * (255 - a) / 255).\n"; *(const char * *)tb_grow(v_lines) = tb_v11247; }
    { const char * tb_v11248 = "// Две части округляются порознь: так получается одинаково на любой видеокарте (шейдер считает первую часть сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v11248; }
    { const char * tb_v11249 = "TB_API void tb_draw_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11249; }
    { const char * tb_v11250 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v11250; }
    { const char * tb_v11251 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11251; }
    { const char * tb_v11252 = "    if (tb_gpu_on) tb_gpu_image_a(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v11252; }
    { const char * tb_v11253 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11253; }
    { const char * tb_v11254 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v11254; }
    { const char * tb_v11255 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v11255; }
    { const char * tb_v11256 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v11256; }
    { const char * tb_v11257 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v11257; }
    { const char * tb_v11258 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11258; }
    { const char * tb_v11259 = "            uint32_t v = src[j * im->w + i], a = v >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v11259; }
    { const char * tb_v11260 = "            if (a == 0) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v11260; }
    { const char * tb_v11261 = "            uint32_t *d = &tb_px[(y + j) * tb_gw + x + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v11261; }
    { const char * tb_v11262 = "            if (a == 255) { *d = v & 0xFFFFFF; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11262; }
    { const char * tb_v11263 = "            uint32_t o = *d, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11263; }
    { const char * tb_v11264 = "            for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11264; }
    { const char * tb_v11265 = "                uint32_t sc = (v >> sh) & 255, dc = (o >> sh) & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v11265; }
    { const char * tb_v11266 = "                uint32_t q = tb_blend_cal ? tb_blend_lut[(sc << 16) | (dc << 8) | a] : (sc * a + 127) / 255 + (dc * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v11266; }
    { const char * tb_v11267 = "                r |= (q > 255 ? 255 : q) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v11267; }
    { const char * tb_v11268 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v11268; }
    { const char * tb_v11269 = "            *d = r;\n"; *(const char * *)tb_grow(v_lines) = tb_v11269; }
    { const char * tb_v11270 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v11270; }
    { const char * tb_v11271 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11271; }
    { const char * tb_v11272 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11272; }
    { const char * tb_v11273 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v11273; }
    { const char * tb_v11274 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11274; }
    { const char * tb_v11275 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v11275; }
    { const char * tb_v11276 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11276; }
    { const char * tb_v11277 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11277; }
    { const char * tb_v11278 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v11278; }
    { const char * tb_v11279 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v11279; }
    { const char * tb_v11280 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11280; }
    { const char * tb_v11281 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v11281; }
    { const char * tb_v11282 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v11282; }
    { const char * tb_v11283 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11283; }
    { const char * tb_v11284 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v11284; }
    { const char * tb_v11285 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v11285; }
    { const char * tb_v11286 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v11286; }
    { const char * tb_v11287 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v11287; }
    { const char * tb_v11288 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v11288; }
    { const char * tb_v11289 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v11289; }
    { const char * tb_v11290 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11290; }
    { const char * tb_v11291 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11291; }
    { const char * tb_v11292 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v11292; }
    { const char * tb_v11293 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v11293; }
    { const char * tb_v11294 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v11294; }
    { const char * tb_v11295 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v11295; }
    { const char * tb_v11296 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v11296; }
    { const char * tb_v11297 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v11297; }
    { const char * tb_v11298 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v11298; }
    { const char * tb_v11299 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11299; }
    { const char * tb_v11300 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v11300; }
    { const char * tb_v11301 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v11301; }
    { const char * tb_v11302 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v11302; }
    { const char * tb_v11303 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v11303; }
    { const char * tb_v11304 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v11304; }
    { const char * tb_v11305 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11305; }
    { const char * tb_v11306 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11306; }
    { const char * tb_v11307 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v11307; }
    { const char * tb_v11308 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v11308; }
    { const char * tb_v11309 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v11309; }
    { const char * tb_v11310 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v11310; }
    { const char * tb_v11311 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v11311; }
    { const char * tb_v11312 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v11312; }
    { const char * tb_v11313 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v11313; }
    { const char * tb_v11314 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v11314; }
    { const char * tb_v11315 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v11315; }
    { const char * tb_v11316 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v11316; }
    { const char * tb_v11317 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v11317; }
    { const char * tb_v11318 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v11318; }
    { const char * tb_v11319 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v11319; }
    { const char * tb_v11320 = "typedef struct { int parent; double piv[3], rot[3], mv[3]; } tb_bone_t;   // кость: родитель, сустав, поворот, сдвиг\n"; *(const char * *)tb_grow(v_lines) = tb_v11320; }
    { const char * tb_v11321 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v11321; }
    { const char * tb_v11322 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v11322; }
    { const char * tb_v11323 = "    int32_t *nrm; long long nrmcap; int nrmok;   // нормаль каждого треугольника в сетке (× 2^14), для света\n"; *(const char * *)tb_grow(v_lines) = tb_v11323; }
    { const char * tb_v11324 = "    double *uv; long long tex;   // картинка сетки (mesh_image, -1 — нет) и (u, v) трёх углов треугольника (NAN — без картинки)\n"; *(const char * *)tb_grow(v_lines) = tb_v11324; }
    { const char * tb_v11325 = "    long long nch, *chr; double *chs, bs[4]; int chok;\n"; *(const char * *)tb_grow(v_lines) = tb_v11325; }
    { const char * tb_v11326 = "    int smooth, alpha, cnok; double shine, glow; double *cn; long long cncap;   // плавный свет, прозрачность 0…255, блеск, свечение; нормали в углах\n"; *(const char * *)tb_grow(v_lines) = tb_v11326; }
    { const char * tb_v11327 = "    tb_bone_t *bones; long long nb, capb; int16_t *sb; float *sw;\n"; *(const char * *)tb_grow(v_lines) = tb_v11327; }
    { const char * tb_v11328 = "    int shp, shc, shok; float shv[16]; float *shvd; long long shvn, shvcap, shused; void *shvb; } tb_mesh;   // gpu func: шейдер точки и углов (-1 — обычный), настройки, углы для видеокарты     // кости и у каждого угла до 4 костей с весами   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v11328; }
    { const char * tb_v11329 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11329; }
    { const char * tb_v11330 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11330; }
    { const char * tb_v11331 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v11331; }
    { const char * tb_v11332 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v11332; }
    { const char * tb_v11333 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11333; }
    { const char * tb_v11334 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11334; }
    { const char * tb_v11335 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v11335; }
    { const char * tb_v11336 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v11336; }
    { const char * tb_v11337 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11337; }
