    { const char * tb_v11476 = "        double e1[3] = { b[0] - a[0], b[1] - a[1], b[2] - a[2] }, e2[3] = { c[0] - a[0], c[1] - a[1], c[2] - a[2] };\n"; *(const char * *)tb_grow(v_lines) = tb_v11476; }
    { const char * tb_v11477 = "        double n[3] = { e1[1] * e2[2] - e1[2] * e2[1], e1[2] * e2[0] - e1[0] * e2[2], e1[0] * e2[1] - e1[1] * e2[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v11477; }
    { const char * tb_v11478 = "        double l = sqrt(n[0] * n[0] + n[1] * n[1] + n[2] * n[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v11478; }
    { const char * tb_v11479 = "        for (int k = 0; k < 3; k++) m->nrm[3 * t + k] = l > 1e-300 ? (int32_t)tb_rnd(n[k] / l * 16384) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11479; }
