    { const char * tb_v11482 = "// цвет грани под светом L (x, y, z, фон) — L уже в осях сетки; front — грань смотрит на нас\n"; *(const char * *)tb_grow(v_lines) = tb_v11482; }
    { const char * tb_v11483 = "// (со спины свет считается от обратной стороны: у пола и листа обе стороны освещены честно)\n"; *(const char * *)tb_grow(v_lines) = tb_v11483; }
    { const char * tb_v11484 = "TB_INL uint32_t tb_shade(uint32_t c, const int32_t *n, const int32_t *L, int front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11484; }
    { const char * tb_v11485 = "    if (L[3] < 0) return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v11485; }
    { const char * tb_v11486 = "    int s = n[0] * L[0] + n[1] * L[1] + n[2] * L[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v11486; }
    { const char * tb_v11487 = "    if (!front) s = -s;\n"; *(const char * *)tb_grow(v_lines) = tb_v11487; }
    { const char * tb_v11488 = "    if (s < 0) s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11488; }
    { const char * tb_v11489 = "    int k = L[3] + (((256 - L[3]) * (s >> 14)) >> 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v11489; }
    { const char * tb_v11490 = "    uint32_t r = (((c >> 16) & 255) * (uint32_t)k + 128) >> 8, g = (((c >> 8) & 255) * (uint32_t)k + 128) >> 8, b = ((c & 255) * (uint32_t)k + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v11490; }
    { const char * tb_v11491 = "    return (c & 0xFF000000u) | (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v11491; }
    { const char * tb_v11492 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11492; }
    { const char * tb_v11493 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v11493; }
    { const char * tb_v11494 = "TB_INL int tb_tri3_plane(const double *sx, const double *sy, const double *dd, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11494; }
    { const char * tb_v11495 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v11495; }
    { const char * tb_v11496 = "    double area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v11496; }
    { const char * tb_v11497 = "    if (fabs(area) < 0.5) return 0;   // смотрит на нас ребром: точек почти нет\n"; *(const char * *)tb_grow(v_lines) = tb_v11497; }
    { const char * tb_v11498 = "    double ia = 1 / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v11498; }
    { const char * tb_v11499 = "    double ax = ((dd[1] - dd[0]) * e2y - (dd[2] - dd[0]) * e1y) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v11499; }
    { const char * tb_v11500 = "    double by = ((dd[2] - dd[0]) * e1x - (dd[1] - dd[0]) * e2x) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v11500; }
    { const char * tb_v11501 = "    if (ax > 1e9) ax = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v11501; }
    { const char * tb_v11502 = "    if (ax < -1e9) ax = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v11502; }
    { const char * tb_v11503 = "    if (by > 1e9) by = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v11503; }
    { const char * tb_v11504 = "    if (by < -1e9) by = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v11504; }
    { const char * tb_v11505 = "    double c0 = dd[0] - ax * sx[0] - by * sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v11505; }
    { const char * tb_v11506 = "    // в целые: точка берётся по центру (2x + 1) / 2, поэтому ax / 2; ещё × 64 для точности\n"; *(const char * *)tb_grow(v_lines) = tb_v11506; }
    { const char * tb_v11507 = "    pl[0] = (uint32_t)tb_rnd(ax * 32); pl[1] = (uint32_t)tb_rnd(by * 32); pl[2] = (uint32_t)tb_rnd(c0 * 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v11507; }
