    { const char * tb_v11509 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11509; }
    { const char * tb_v11510 = "// углы сетки после камеры: место перед камерой и на экране (округлённое), глубина D\n"; *(const char * *)tb_grow(v_lines) = tb_v11510; }
    { const char * tb_v11511 = "typedef struct { double cx, cy, cz, sx, sy, dd; long long rx, ry; int front, near_ok; } tb_3v;\n"; *(const char * *)tb_grow(v_lines) = tb_v11511; }
