    { const char * tb_v11516 = "// ---- картинка на сетке: плоскости u·W и v·W по трём углам ----\n"; *(const char * *)tb_grow(v_lines) = tb_v11516; }
    { const char * tb_v11517 = "// треугольник t сетки рисуется картинкой? (есть картинка, у треугольника есть (u, v), видеокарта умеет)\n"; *(const char * *)tb_grow(v_lines) = tb_v11517; }
    { const char * tb_v11518 = "TB_INL int tb_tex_on(const tb_mesh *m, long long t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11518; }
    { const char * tb_v11519 = "    return m->tex >= 0 && m->uv && !__builtin_isnan(m->uv[6 * t]) && (!tb_gpu_on || tb_gpu_tex);\n"; *(const char * *)tb_grow(v_lines) = tb_v11519; }
    { const char * tb_v11520 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11520; }
    { const char * tb_v11521 = "// (u, v) угла в 1/16 точки картинки, не дальше ±2^19 (чтобы плоскости влезли в 64 бита)\n"; *(const char * *)tb_grow(v_lines) = tb_v11521; }
    { const char * tb_v11522 = "TB_INL long long tb_tex_q(double u, int w) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11522; }
    { const char * tb_v11523 = "    double q = u * w * 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v11523; }
    { const char * tb_v11524 = "    if (!(q > -524288)) q = -524288;   // и NaN\n"; *(const char * *)tb_grow(v_lines) = tb_v11524; }
    { const char * tb_v11525 = "    if (q > 524288) q = 524288;\n"; *(const char * *)tb_grow(v_lines) = tb_v11525; }
    { const char * tb_v11526 = "    return tb_rnd(q);\n"; *(const char * *)tb_grow(v_lines) = tb_v11526; }
    { const char * tb_v11527 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11527; }
    { const char * tb_v11528 = "// плоскость S по трём углам в целых: та же формула, что у плоскости глубины в tb_m3_tri\n"; *(const char * *)tb_grow(v_lines) = tb_v11528; }
    { const char * tb_v11529 = "static void tb_tex_plane_i(const long long *a, const long long *b, const long long *c, const long long *S, int64_t *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11529; }
    { const char * tb_v11530 = "    long long s0 = S[0], s1 = S[1], s2 = S[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v11530; }
    { const char * tb_v11531 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v11531; }
    { const char * tb_v11532 = "    if (area < 0) { const long long *k = b; b = c; c = k; long long ks = s1; s1 = s2; s2 = ks; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11532; }
    { const char * tb_v11533 = "    if (area == 0) { o[0] = o[1] = 0; o[2] = 64 * s0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11533; }
    { const char * tb_v11534 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = s1 - s0, d2 = s2 - s0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11534; }
    { const char * tb_v11535 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v11535; }
    { const char * tb_v11536 = "    o[0] = A; o[1] = B; o[2] = 64 * s0 - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v11536; }
    { const char * tb_v11537 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11537; }
    { const char * tb_v11538 = "// запись текстуры для углов (x, y, D) в целых и (u, v) углов треугольника t\n"; *(const char * *)tb_grow(v_lines) = tb_v11538; }
    { const char * tb_v11539 = "static void tb_tex_rec_i(const tb_mesh *m, long long t, const long long *a, const long long *b, const long long *c, tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11539; }
    { const char * tb_v11540 = "    const tb_image *im = &tb_imgs[m->tex];\n"; *(const char * *)tb_grow(v_lines) = tb_v11540; }
    { const char * tb_v11541 = "    const double *q = m->uv + 6 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v11541; }
