    { const char * tb_v11545 = "        long long W = (16777216 - p[i][2]) >> 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v11545; }
    { const char * tb_v11546 = "        if (W < 1) W = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11546; }
    { const char * tb_v11547 = "        su[i] = tb_tex_q(q[2 * i], im->w) * W; sv[i] = tb_tex_q(q[2 * i + 1], im->h) * W;\n"; *(const char * *)tb_grow(v_lines) = tb_v11547; }
    { const char * tb_v11548 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11548; }
    { const char * tb_v11549 = "    int64_t pu[3], pv[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v11549; }
    { const char * tb_v11550 = "    tb_tex_plane_i(a, b, c, su, pu); tb_tex_plane_i(a, b, c, sv, pv);\n"; *(const char * *)tb_grow(v_lines) = tb_v11550; }
    { const char * tb_v11551 = "    tx->au = pu[0]; tx->bu = pu[1]; tx->cu = pu[2]; tx->av = pv[0]; tx->bv = pv[1]; tx->cv = pv[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v11551; }
    { const char * tb_v11552 = "    tx->off = im->off; tx->w = (uint32_t)im->w; tx->h = (uint32_t)im->h; tx->pad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11552; }
    { const char * tb_v11553 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11553; }
    { const char * tb_v11554 = "// то же в дробях (старый путь): углы (x, y, D) после проекции и (u, v) каждого угла\n"; *(const char * *)tb_grow(v_lines) = tb_v11554; }
    { const char * tb_v11555 = "static void tb_tex_rec_d(const tb_mesh *m, int n, const double *sx, const double *sy, const double *dd, const double *uu, const double *vv, tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11555; }
    { const char * tb_v11556 = "    const tb_image *im = &tb_imgs[m->tex];\n"; *(const char * *)tb_grow(v_lines) = tb_v11556; }
