    { const char * tb_v11558 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11558; }
    { const char * tb_v11559 = "        double W = floor((16777216 - dd[i]) / 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v11559; }
    { const char * tb_v11560 = "        if (W < 1) W = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11560; }
    { const char * tb_v11561 = "        su[i] = (double)tb_tex_q(uu[i], im->w) * W; sv[i] = (double)tb_tex_q(vv[i], im->h) * W;\n"; *(const char * *)tb_grow(v_lines) = tb_v11561; }
    { const char * tb_v11562 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11562; }
    { const char * tb_v11563 = "    (void)n;\n"; *(const char * *)tb_grow(v_lines) = tb_v11563; }
    { const char * tb_v11564 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0], area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v11564; }
    { const char * tb_v11565 = "    double *S[2] = { su, sv };\n"; *(const char * *)tb_grow(v_lines) = tb_v11565; }
    { const char * tb_v11566 = "    int64_t o[6];\n"; *(const char * *)tb_grow(v_lines) = tb_v11566; }
    { const char * tb_v11567 = "    for (int k = 0; k < 2; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11567; }
    { const char * tb_v11568 = "        double ax = 0, by = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11568; }
    { const char * tb_v11569 = "        if (fabs(area) >= 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11569; }
    { const char * tb_v11570 = "            ax = ((S[k][1] - S[k][0]) * e2y - (S[k][2] - S[k][0]) * e1y) / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v11570; }
