    { const char * tb_v11575 = "        if (by > 1e15) by = 1e15;\n"; *(const char * *)tb_grow(v_lines) = tb_v11575; }
    { const char * tb_v11576 = "        if (by < -1e15) by = -1e15;\n"; *(const char * *)tb_grow(v_lines) = tb_v11576; }
    { const char * tb_v11577 = "        double c0 = S[k][0] - ax * sx[0] - by * sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v11577; }
    { const char * tb_v11578 = "        o[3 * k] = tb_rnd(ax * 32); o[3 * k + 1] = tb_rnd(by * 32); o[3 * k + 2] = tb_rnd(c0 * 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v11578; }
