    { const char * tb_v11582 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11582; }
    { const char * tb_v11583 = "// R — поворот сетки (3 × 3): угол p в мире = R p + (x, y, z)\n"; *(const char * *)tb_grow(v_lines) = tb_v11583; }
    { const char * tb_v11584 = "static void tb_draw_mesh_d(tb_mesh *m, double x, double y, double z, double R[3][3], const int32_t *L, long long t0, long long t1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11584; }
    { const char * tb_v11585 = "    if (m->nv > tb_3vcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11585; }
