    { const char * tb_v11794 = "        if (g && g->m == 3u && g->x0 == (int32_t)go->id && g->y0 == go->cull && g->ox == t0 && g->oy == tn &&\n"; *(const char * *)tb_grow(v_lines) = tb_v11794; }
    { const char * tb_v11795 = "            g->x1 + g->y1 == go->ri && (long long)(g->y1 + 1) * tn < 2000000000) g->y1++;   // та же сетка подряд: одним вызовом\n"; *(const char * *)tb_grow(v_lines) = tb_v11795; }
