    { const char * tb_v11805 = "        tb_3ist = (long long *)realloc(tb_3ist, sizeof(long long) * tb_3icap / 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v11805; }
    { const char * tb_v11806 = "        memset(tb_3ist, 0, sizeof(long long) * (tb_3icap / 3));\n"; *(const char * *)tb_grow(v_lines) = tb_v11806; }
    { const char * tb_v11807 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11807; }
    { const char * tb_v11808 = "    long long fq = tb_m3_f(), gen = ++tb_3igen;\n"; *(const char * *)tb_grow(v_lines) = tb_v11808; }
    { const char * tb_v11809 = "    for (long long t = t0; t < t0 + tn; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11809; }
