    { const char * tb_v11819 = "        tb_tri_draw_x(q, tb_shade(m->c[t], m->nrm + 3 * t, go->rec.r + 12, fr == 1), pl, gpu, cpu);\n"; *(const char * *)tb_grow(v_lines) = tb_v11819; }
