    { const char * tb_v11823 = "// куски сетки: треугольники делятся пополам по самой длинной стороне, пока в куске не больше 256.\n"; *(const char * *)tb_grow(v_lines) = tb_v11823; }
    { const char * tb_v11824 = "// Треугольники переставляются так, чтобы каждый кусок шёл подряд; у каждого куска свой шар\n"; *(const char * *)tb_grow(v_lines) = tb_v11824; }
    { const char * tb_v11825 = "static int tb_kd_ax;\n"; *(const char * *)tb_grow(v_lines) = tb_v11825; }
    { const char * tb_v11826 = "static const float *tb_kd_c;\n"; *(const char * *)tb_grow(v_lines) = tb_v11826; }
    { const char * tb_v11827 = "static int tb_kd_cmp(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11827; }
    { const char * tb_v11828 = "    float x = tb_kd_c[3 * *(const uint32_t *)a + tb_kd_ax], y = tb_kd_c[3 * *(const uint32_t *)b + tb_kd_ax];\n"; *(const char * *)tb_grow(v_lines) = tb_v11828; }
    { const char * tb_v11829 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v11829; }
    { const char * tb_v11830 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11830; }
    { const char * tb_v11831 = "static void tb_kd(tb_mesh *m, uint32_t *ix, long long n, const float *cen, long long *at) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11831; }
    { const char * tb_v11832 = "    if (n <= 256) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11832; }
    { const char * tb_v11833 = "        long long c = m->nch++;\n"; *(const char * *)tb_grow(v_lines) = tb_v11833; }
    { const char * tb_v11834 = "        m->chr[2 * c] = *at; m->chr[2 * c + 1] = n; *at += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v11834; }
    { const char * tb_v11835 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11835; }
    { const char * tb_v11836 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11836; }
    { const char * tb_v11837 = "    float lo[3] = { 1e30f, 1e30f, 1e30f }, hi[3] = { -1e30f, -1e30f, -1e30f };\n"; *(const char * *)tb_grow(v_lines) = tb_v11837; }
    { const char * tb_v11838 = "    for (long long i = 0; i < n; i++) for (int k = 0; k < 3; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11838; }
