    { const char * tb_v11843 = "    int ax = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11843; }
    { const char * tb_v11844 = "    for (int k = 1; k < 3; k++) if (hi[k] - lo[k] > hi[ax] - lo[ax]) ax = k;\n"; *(const char * *)tb_grow(v_lines) = tb_v11844; }
