    { const char * tb_v12145 = "            L[9 + i] = k->piv[i] + k->mv[i] - (R[i][0] * k->piv[0] + R[i][1] * k->piv[1] + R[i][2] * k->piv[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v12145; }
