    { const char * tb_v12170 = "        for (int k = 0; k < 3; k++) { fa[3 * t + k] = n[k]; fn[3 * t + k] = l > 1e-300 ? n[k] / l : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12170; }
