    { const char * tb_v12178 = "    long long *st = (long long *)calloc((size_t)m->nv + 1, sizeof(long long)), *ls = (long long *)malloc(sizeof(long long) * 3 * (size_t)(m->n ? m->n : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v12178; }
    { const char * tb_v12179 = "    for (long long t = 0; t < 3 * m->n; t++) st[m->t[t] + 1]++;\n"; *(const char * *)tb_grow(v_lines) = tb_v12179; }
