    { const char * tb_v12227 = "        double p[3] = { m->v[3 * k], m->v[3 * k + 1], m->v[3 * k + 2] };\n"; *(const char * *)tb_grow(v_lines) = tb_v12227; }
    { const char * tb_v12228 = "        if (vm) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12228; }
