    { const char * tb_v12886 = "        {\"cmd\", TB_K_CTRL},       // на Linux и Windows вместо Command — Ctrl: одна программа для всех\n"; *(const char * *)tb_grow(v_lines) = tb_v12886; }
    { const char * tb_v12887 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v12887; }
    { const char * tb_v12888 = "        {\"ctrl\", TB_K_CTRL}, {\"alt\", TB_K_ALT}, {\"delete\", TB_K_DEL}, {\"home\", TB_K_HOME}, {\"end\", TB_K_END},\n"; *(const char * *)tb_grow(v_lines) = tb_v12888; }
    { const char * tb_v12889 = "        {\"pageup\", TB_K_PGUP}, {\"pagedown\", TB_K_PGDN},\n"; *(const char * *)tb_grow(v_lines) = tb_v12889; }
    { const char * tb_v12890 = "        {\"f1\", TB_K_F1}, {\"f2\", TB_K_F1 + 1}, {\"f3\", TB_K_F1 + 2}, {\"f4\", TB_K_F1 + 3}, {\"f5\", TB_K_F1 + 4}, {\"f6\", TB_K_F1 + 5},\n"; *(const char * *)tb_grow(v_lines) = tb_v12890; }
    { const char * tb_v12891 = "        {\"f7\", TB_K_F1 + 6}, {\"f8\", TB_K_F1 + 7}, {\"f9\", TB_K_F1 + 8}, {\"f10\", TB_K_F1 + 9}, {\"f11\", TB_K_F1 + 10}, {\"f12\", TB_K_F1 + 11} };\n"; *(const char * *)tb_grow(v_lines) = tb_v12891; }
    { const char * tb_v12892 = "    for (unsigned i = 0; i < sizeof names / sizeof names[0]; i++) if (strcmp(name, names[i].n) == 0) return tb_key_at(names[i].k);\n"; *(const char * *)tb_grow(v_lines) = tb_v12892; }
    { const char * tb_v12893 = "    if (name[0] && !name[1]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12893; }
    { const char * tb_v12894 = "        int ch = (unsigned char)name[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v12894; }
    { const char * tb_v12895 = "        if (ch >= 'a' && ch <= 'z') ch -= 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v12895; }
    { const char * tb_v12896 = "        return tb_key_at(ch);\n"; *(const char * *)tb_grow(v_lines) = tb_v12896; }
    { const char * tb_v12897 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12897; }
    { const char * tb_v12898 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12898; }
    { const char * tb_v12899 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12899; }
    { const char * tb_v12900 = "TB_API long long tb_mouse_x(void) { return tb_mx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12900; }
    { const char * tb_v12901 = "TB_API long long tb_mouse_y(void) { return tb_my; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12901; }
    { const char * tb_v12902 = "TB_API int tb_mouse_down(void) { int d = tb_mdown || tb_mtap; tb_mtap = 0; return d; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12902; }
    { const char * tb_v12903 = "TB_API long long tb_mouse_wheel(void) { int w = tb_wheel; tb_wheel = 0; return w; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12903; }
    { const char * tb_v12904 = "TB_API int tb_mouse_back(void) { int d = tb_mside[0] || tb_mside_tap[0]; tb_mside_tap[0] = 0; return d; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12904; }
    { const char * tb_v12905 = "TB_API int tb_mouse_forward(void) { int d = tb_mside[1] || tb_mside_tap[1]; tb_mside_tap[1] = 0; return d; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12905; }
    { const char * tb_v12906 = "// ---------- геймпад: pad_count(), pad_down(n, \"a\"), pad_axis(n, \"lx\") ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v12906; }
    { const char * tb_v12907 = "// Кнопки: a b x y l1 r1 l2 r2 l3 r3 start select home up down left right.\n"; *(const char * *)tb_grow(v_lines) = tb_v12907; }
    { const char * tb_v12908 = "// Оси (от -1 до 1, курки от 0 до 1): lx ly rx ry l2 r2. Вниз и вправо — плюс. n — номер геймпада с 0.\n"; *(const char * *)tb_grow(v_lines) = tb_v12908; }
    { const char * tb_v12909 = "// Mac — GameController, Windows — XInput, Linux — /dev/input/js*. В ядре без ОС геймпадов нет.\n"; *(const char * *)tb_grow(v_lines) = tb_v12909; }
    { const char * tb_v12910 = "enum { TB_PB_A, TB_PB_B, TB_PB_X, TB_PB_Y, TB_PB_L1, TB_PB_R1, TB_PB_L2, TB_PB_R2, TB_PB_L3, TB_PB_R3,\n"; *(const char * *)tb_grow(v_lines) = tb_v12910; }
    { const char * tb_v12911 = "       TB_PB_START, TB_PB_SELECT, TB_PB_HOME, TB_PB_UP, TB_PB_DOWN, TB_PB_LEFT, TB_PB_RIGHT, TB_PB_N };\n"; *(const char * *)tb_grow(v_lines) = tb_v12911; }
    { const char * tb_v12912 = "enum { TB_PA_LX, TB_PA_LY, TB_PA_RX, TB_PA_RY, TB_PA_L2, TB_PA_R2, TB_PA_N };\n"; *(const char * *)tb_grow(v_lines) = tb_v12912; }
    { const char * tb_v12913 = "#define TB_PADS 4\n"; *(const char * *)tb_grow(v_lines) = tb_v12913; }
    { const char * tb_v12914 = "typedef struct { int on; int b[TB_PB_N]; double a[TB_PA_N]; } tb_pad;\n"; *(const char * *)tb_grow(v_lines) = tb_v12914; }
    { const char * tb_v12915 = "TB_API tb_pad tb_pads[TB_PADS];\n"; *(const char * *)tb_grow(v_lines) = tb_v12915; }
    { const char * tb_v12916 = "TB_API long long tb_pad_t = -1000;   // когда опрашивали (мс): не чаще раза в 4 мс\n"; *(const char * *)tb_grow(v_lines) = tb_v12916; }
    { const char * tb_v12917 = "#if defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v12917; }
    { const char * tb_v12918 = "TB_API void tb_pad_poll(void) {}\n"; *(const char * *)tb_grow(v_lines) = tb_v12918; }
    { const char * tb_v12919 = "#elif defined(__APPLE__)\n"; *(const char * *)tb_grow(v_lines) = tb_v12919; }
    { const char * tb_v12920 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12920; }
    { const char * tb_v12921 = "    static int tried = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12921; }
    { const char * tb_v12922 = "    if (!tried) { tried = 1; dlopen(\"/System/Library/Frameworks/GameController.framework/GameController\", RTLD_LAZY); }\n"; *(const char * *)tb_grow(v_lines) = tb_v12922; }
    { const char * tb_v12923 = "    id cls = TB_CLS(\"GCController\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12923; }
    { const char * tb_v12924 = "    for (int p = 0; p < TB_PADS; p++) tb_pads[p].on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12924; }
    { const char * tb_v12925 = "    if (!cls) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v12925; }
    { const char * tb_v12926 = "    id all = TB_MSG(id, cls, \"controllers\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12926; }
    { const char * tb_v12927 = "    unsigned long n = all ? TB_MSG(unsigned long, all, \"count\") : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12927; }
    { const char * tb_v12928 = "    for (unsigned long i = 0; i < n && i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12928; }
    { const char * tb_v12929 = "        id c = TB_MSG1(id, all, \"objectAtIndex:\", unsigned long, i);\n"; *(const char * *)tb_grow(v_lines) = tb_v12929; }
    { const char * tb_v12930 = "        id g = TB_MSG(id, c, \"extendedGamepad\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12930; }
    { const char * tb_v12931 = "        if (!g) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v12931; }
    { const char * tb_v12932 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v12932; }
    { const char * tb_v12933 = "        p->on = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12933; }
    { const char * tb_v12934 = "        static const char *bn[TB_PB_N] = { \"buttonA\", \"buttonB\", \"buttonX\", \"buttonY\", \"leftShoulder\", \"rightShoulder\",\n"; *(const char * *)tb_grow(v_lines) = tb_v12934; }
    { const char * tb_v12935 = "            \"leftTrigger\", \"rightTrigger\", \"leftThumbstickButton\", \"rightThumbstickButton\", \"buttonMenu\", \"buttonOptions\", \"buttonHome\", 0, 0, 0, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v12935; }
    { const char * tb_v12936 = "        for (int k = 0; k < TB_PB_N; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12936; }
    { const char * tb_v12937 = "            if (!bn[k]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v12937; }
    { const char * tb_v12938 = "            if (!class_respondsToSelector(object_getClass(g), sel_getUid(bn[k]))) { p->b[k] = 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12938; }
    { const char * tb_v12939 = "            id el = TB_MSG(id, g, bn[k]);\n"; *(const char * *)tb_grow(v_lines) = tb_v12939; }
    { const char * tb_v12940 = "            p->b[k] = el ? (int)TB_MSG(BOOL, el, \"isPressed\") : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12940; }
    { const char * tb_v12941 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v12941; }
    { const char * tb_v12942 = "        id dp = TB_MSG(id, g, \"dpad\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12942; }
    { const char * tb_v12943 = "        p->b[TB_PB_UP] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"up\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12943; }
    { const char * tb_v12944 = "        p->b[TB_PB_DOWN] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"down\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12944; }
    { const char * tb_v12945 = "        p->b[TB_PB_LEFT] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"left\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12945; }
    { const char * tb_v12946 = "        p->b[TB_PB_RIGHT] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"right\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12946; }
    { const char * tb_v12947 = "        id ls = TB_MSG(id, g, \"leftThumbstick\"), rs = TB_MSG(id, g, \"rightThumbstick\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12947; }
    { const char * tb_v12948 = "        p->a[TB_PA_LX] = TB_MSG(float, TB_MSG(id, ls, \"xAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12948; }
    { const char * tb_v12949 = "        p->a[TB_PA_LY] = -TB_MSG(float, TB_MSG(id, ls, \"yAxis\"), \"value\");   // у Apple вверх — плюс\n"; *(const char * *)tb_grow(v_lines) = tb_v12949; }
    { const char * tb_v12950 = "        p->a[TB_PA_RX] = TB_MSG(float, TB_MSG(id, rs, \"xAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12950; }
    { const char * tb_v12951 = "        p->a[TB_PA_RY] = -TB_MSG(float, TB_MSG(id, rs, \"yAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12951; }
    { const char * tb_v12952 = "        p->a[TB_PA_L2] = TB_MSG(float, TB_MSG(id, g, \"leftTrigger\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12952; }
    { const char * tb_v12953 = "        p->a[TB_PA_R2] = TB_MSG(float, TB_MSG(id, g, \"rightTrigger\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12953; }
    { const char * tb_v12954 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12954; }
    { const char * tb_v12955 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12955; }
    { const char * tb_v12956 = "#elif defined(_WIN32)\n"; *(const char * *)tb_grow(v_lines) = tb_v12956; }
    { const char * tb_v12957 = "typedef struct { unsigned short buttons; unsigned char lt, rt; short lx, ly, rx, ry; } tb_xpad;\n"; *(const char * *)tb_grow(v_lines) = tb_v12957; }
    { const char * tb_v12958 = "typedef struct { unsigned long packet; tb_xpad pad; } tb_xstate;\n"; *(const char * *)tb_grow(v_lines) = tb_v12958; }
    { const char * tb_v12959 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12959; }
    { const char * tb_v12960 = "    static unsigned long (__stdcall *get)(unsigned long, tb_xstate *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12960; }
    { const char * tb_v12961 = "    static int tried = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12961; }
    { const char * tb_v12962 = "    if (!tried) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12962; }
    { const char * tb_v12963 = "        tried = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12963; }
    { const char * tb_v12964 = "        HMODULE h = LoadLibraryA(\"xinput1_4.dll\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12964; }
    { const char * tb_v12965 = "        if (!h) h = LoadLibraryA(\"xinput9_1_0.dll\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12965; }
    { const char * tb_v12966 = "        if (h) get = (unsigned long (__stdcall *)(unsigned long, tb_xstate *))GetProcAddress(h, \"XInputGetState\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12966; }
    { const char * tb_v12967 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12967; }
    { const char * tb_v12968 = "    for (int i = 0; i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12968; }
    { const char * tb_v12969 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v12969; }
    { const char * tb_v12970 = "        tb_xstate st; memset(&st, 0, sizeof st);\n"; *(const char * *)tb_grow(v_lines) = tb_v12970; }
    { const char * tb_v12971 = "        p->on = get && get((unsigned long)i, &st) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12971; }
    { const char * tb_v12972 = "        if (!p->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v12972; }
    { const char * tb_v12973 = "        unsigned short w = st.pad.buttons;\n"; *(const char * *)tb_grow(v_lines) = tb_v12973; }
    { const char * tb_v12974 = "        static const unsigned short bit[TB_PB_N] = { 0x1000, 0x2000, 0x4000, 0x8000, 0x0100, 0x0200, 0, 0, 0x0040, 0x0080, 0x0010, 0x0020, 0, 0x0001, 0x0002, 0x0004, 0x0008 };\n"; *(const char * *)tb_grow(v_lines) = tb_v12974; }
    { const char * tb_v12975 = "        for (int k = 0; k < TB_PB_N; k++) p->b[k] = bit[k] ? (w & bit[k]) != 0 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12975; }
    { const char * tb_v12976 = "        p->b[TB_PB_L2] = st.pad.lt > 30; p->b[TB_PB_R2] = st.pad.rt > 30;\n"; *(const char * *)tb_grow(v_lines) = tb_v12976; }
    { const char * tb_v12977 = "        p->a[TB_PA_LX] = st.pad.lx / 32767.0; p->a[TB_PA_LY] = -st.pad.ly / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12977; }
    { const char * tb_v12978 = "        p->a[TB_PA_RX] = st.pad.rx / 32767.0; p->a[TB_PA_RY] = -st.pad.ry / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12978; }
    { const char * tb_v12979 = "        p->a[TB_PA_L2] = st.pad.lt / 255.0; p->a[TB_PA_R2] = st.pad.rt / 255.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12979; }
    { const char * tb_v12980 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12980; }
    { const char * tb_v12981 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12981; }
    { const char * tb_v12982 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v12982; }
    { const char * tb_v12983 = "#include <fcntl.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v12983; }
    { const char * tb_v12984 = "TB_API int tb_pad_fd[TB_PADS] = { -1, -1, -1, -1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v12984; }
    { const char * tb_v12985 = "TB_API long long tb_pad_look = -100000;\n"; *(const char * *)tb_grow(v_lines) = tb_v12985; }
    { const char * tb_v12986 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12986; }
    { const char * tb_v12987 = "    // новые геймпады ищем раз в 2 секунды\n"; *(const char * *)tb_grow(v_lines) = tb_v12987; }
    { const char * tb_v12988 = "    long long now = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v12988; }
    { const char * tb_v12989 = "    if (now - tb_pad_look > 2000) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12989; }
    { const char * tb_v12990 = "        tb_pad_look = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v12990; }
    { const char * tb_v12991 = "        for (int i = 0; i < TB_PADS; i++) if (tb_pad_fd[i] < 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12991; }
    { const char * tb_v12992 = "            char path[32]; snprintf(path, sizeof path, \"/dev/input/js%d\", i);\n"; *(const char * *)tb_grow(v_lines) = tb_v12992; }
    { const char * tb_v12993 = "            tb_pad_fd[i] = open(path, O_RDONLY | O_NONBLOCK);\n"; *(const char * *)tb_grow(v_lines) = tb_v12993; }
    { const char * tb_v12994 = "            if (tb_pad_fd[i] >= 0) memset(&tb_pads[i], 0, sizeof tb_pads[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v12994; }
    { const char * tb_v12995 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v12995; }
    { const char * tb_v12996 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12996; }
    { const char * tb_v12997 = "    // раскладка xpad (Xbox и большинство совместимых): кнопки 0 A, 1 B, 2 X, 3 Y, 4 LB, 5 RB, 6 back, 7 start, 8 home, 9 L3, 10 R3;\n"; *(const char * *)tb_grow(v_lines) = tb_v12997; }
    { const char * tb_v12998 = "    // оси 0 lx, 1 ly, 2 lt, 3 rx, 4 ry, 5 rt, 6 крестовина x, 7 крестовина y\n"; *(const char * *)tb_grow(v_lines) = tb_v12998; }
    { const char * tb_v12999 = "    static const int bmap[11] = { TB_PB_A, TB_PB_B, TB_PB_X, TB_PB_Y, TB_PB_L1, TB_PB_R1, TB_PB_SELECT, TB_PB_START, TB_PB_HOME, TB_PB_L3, TB_PB_R3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v12999; }
    { const char * tb_v13000 = "    for (int i = 0; i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13000; }
    { const char * tb_v13001 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v13001; }
    { const char * tb_v13002 = "        p->on = tb_pad_fd[i] >= 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13002; }
    { const char * tb_v13003 = "        if (!p->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v13003; }
    { const char * tb_v13004 = "        struct { unsigned int time; short value; unsigned char type, number; } e;\n"; *(const char * *)tb_grow(v_lines) = tb_v13004; }
    { const char * tb_v13005 = "        long long got;\n"; *(const char * *)tb_grow(v_lines) = tb_v13005; }
    { const char * tb_v13006 = "        while ((got = read(tb_pad_fd[i], &e, sizeof e)) == (long long)sizeof e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13006; }
    { const char * tb_v13007 = "            int t = e.type & 0x7f;\n"; *(const char * *)tb_grow(v_lines) = tb_v13007; }
    { const char * tb_v13008 = "            if (t == 1 && e.number < 11) p->b[bmap[e.number]] = e.value != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13008; }
    { const char * tb_v13009 = "            else if (t == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13009; }
    { const char * tb_v13010 = "                double v = e.value / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13010; }
    { const char * tb_v13011 = "                if (v < -1) v = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13011; }
    { const char * tb_v13012 = "                switch (e.number) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13012; }
    { const char * tb_v13013 = "                case 0: p->a[TB_PA_LX] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v13013; }
    { const char * tb_v13014 = "                case 1: p->a[TB_PA_LY] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v13014; }
    { const char * tb_v13015 = "                case 2: p->a[TB_PA_L2] = (v + 1) / 2; p->b[TB_PB_L2] = v > -0.75; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v13015; }
