    { const char * tb_v13088 = "// ---------- для файла .ll (TB_LL): библиотека видна снаружи через tb_x_* ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v13088; }
    { const char * tb_v13089 = "// Сама библиотека — static: так её лучше встраивать. Эти обёртки — её «дверь» для LLVM.\n"; *(const char * *)tb_grow(v_lines) = tb_v13089; }
    { const char * tb_v13090 = "// Без clang (llvm-link + opt + llc) библиотека заранее лежит в файле .bc, а программа\n"; *(const char * *)tb_grow(v_lines) = tb_v13090; }
    { const char * tb_v13091 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v13091; }
    { const char * tb_v13092 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v13092; }
    { const char * tb_v13093 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v13093; }
    { const char * tb_v13094 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v13094; }
    { const char * tb_v13095 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v13095; }
    { const char * tb_v13096 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v13096; }
    { const char * tb_v13097 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v13097; }
    { const char * tb_v13098 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v13098; }
    { const char * tb_v13099 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v13099; }
    { const char * tb_v13100 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v13100; }
    { const char * tb_v13101 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v13101; }
    { const char * tb_v13102 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v13102; }
    { const char * tb_v13103 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v13103; }
    { const char * tb_v13104 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v13104; }
    { const char * tb_v13105 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v13105; }
    { const char * tb_v13106 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v13106; }
    { const char * tb_v13107 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v13107; }
    { const char * tb_v13108 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v13108; }
    { const char * tb_v13109 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v13109; }
    { const char * tb_v13110 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v13110; }
    { const char * tb_v13111 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v13111; }
    { const char * tb_v13112 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v13112; }
