    { const char * tb_v13115 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v13115; }
    { const char * tb_v13116 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v13116; }
    { const char * tb_v13117 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v13117; }
    { const char * tb_v13118 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v13118; }
    { const char * tb_v13119 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v13119; }
    { const char * tb_v13120 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v13120; }
    { const char * tb_v13121 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v13121; }
    { const char * tb_v13122 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13122; }
    { const char * tb_v13123 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13123; }
    { const char * tb_v13124 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v13124; }
    { const char * tb_v13125 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v13125; }
    { const char * tb_v13126 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13126; }
    { const char * tb_v13127 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13127; }
    { const char * tb_v13128 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13128; }
    { const char * tb_v13129 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13129; }
    { const char * tb_v13130 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13130; }
    { const char * tb_v13131 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13131; }
    { const char * tb_v13132 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v13132; }
    { const char * tb_v13133 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13133; }
    { const char * tb_v13134 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v13134; }
    { const char * tb_v13135 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13135; }
    { const char * tb_v13136 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v13136; }
    { const char * tb_v13137 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v13137; }
    { const char * tb_v13138 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v13138; }
    { const char * tb_v13139 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v13139; }
    { const char * tb_v13140 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v13140; }
    { const char * tb_v13141 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v13141; }
    { const char * tb_v13142 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13142; }
    { const char * tb_v13143 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13143; }
    { const char * tb_v13144 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v13144; }
    { const char * tb_v13145 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v13145; }
    { const char * tb_v13146 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13146; }
    { const char * tb_v13147 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v13147; }
    { const char * tb_v13148 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13148; }
    { const char * tb_v13149 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13149; }
    { const char * tb_v13150 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v13150; }
    { const char * tb_v13151 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13151; }
    { const char * tb_v13152 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13152; }
    { const char * tb_v13153 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v13153; }
    { const char * tb_v13154 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13154; }
    { const char * tb_v13155 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v13155; }
    { const char * tb_v13156 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v13156; }
